/* City Brush v37 · landmark intro cards · Tokyo (all 111 targets of tyo/targets.json, plus site, site-building and far-terrain entries)
   Data contract: SC/lm31/BRIEF.md. Labelled keys: k kind, y year, a architect, h height m, fl floors, d description, x extra facts.
   'site:<key>' copies exist for the targets that may be built as SITES (the site key = the target key); 'site:<key>:<OSM en name>'
   entries for a few site building labels (only buildings we are sure of). Secondary pieces (<key>_b …) need no entry: the card
   resolves them to their parent by key prefix.
   Far terrain (lm33/fuji labels, en -> key): Mount Fuji -> far:fuji, Hakone -> far:hakone, Tanzawa Mountains -> far:tanzawa,
   Sagami Bay -> far:sagami, Lake Kawaguchi -> far:kawaguchi, Lake Yamanaka -> far:yamanaka, Lake Sai -> far:sai,
   Lake Shōji -> far:shoji, Lake Motosu -> far:motosu, Lake Ashi -> far:ashi; far:fivelakes = the Fuji Five Lakes as a group.
   Original writing; fields left out where not certain; no brand names for the generic-form models. Generated by build.js. */
Object.assign(window.LM_INFO = window.LM_INFO || {}, {

  /* marunouchi */
  tytokyostation: {"k":{"zh":"火车站站舍","en":"Railway station building"},"y":"1914","a":{"zh":"辰野金吾","en":"Tatsuno Kingo"},"fl":3,"d":{"zh":"东京站丸之内站舍是一座长约335米的红砖建筑，1914年启用。1945年空袭烧毁了南北两座圆顶和三楼，战后只修成两层。2012年站舍按1914年原貌复原，重新建起圆顶和第三层，现为国家重要文化财产。","en":"The Marunouchi side of Tokyo Station is a red-brick building about 335 metres long, opened in 1914. Air raids in 1945 burned its two domes and top floor, and it was patched up with only two storeys. In 2012 it was restored to its 1914 form, domes included. It is an Important Cultural Property."},"x":[{"zh":"站舍内设有一家车站酒店","en":"A hotel is housed inside the station building"},{"zh":"新干线和多条JR线路在这里交会","en":"Shinkansen and many JR lines meet here"}]},
  tymarubiru: {"k":{"zh":"摩天大楼","en":"Skyscraper"},"y":"2002","h":179,"fl":37,"d":{"zh":"丸之内大厦于2002年在1923年老楼的原址上重建。它的低层裙楼高约31米，延续了丸之内一带老建筑统一的“百尺”檐口高度，塔楼则从裙楼上方退后升起。底部几层是商场，顶层设有餐厅，可以俯瞰东京站和皇居。","en":"The Marunouchi Building was rebuilt in 2002 on the site of its 1923 predecessor. Its podium is about 31 metres high, keeping the old \"100 shaku\" cornice line shared by the area’s early office blocks, and the tower is set back above it. Shops fill the lower floors, and restaurants at the top look over Tokyo Station and the Imperial Palace."}},
  tyshinmaru: {"k":{"zh":"摩天大楼","en":"Skyscraper"},"y":"2007","h":197.6,"fl":38,"d":{"zh":"新丸之内大厦与丸之内大厦隔着行幸通相望，2007年落成，取代了1952年的旧楼。它同样采用约31米高的裙楼加退台塔楼的做法，使两座大厦像一对门柱守在站前广场两侧。七楼有一处开放式露台，可以眺望红砖站舍。","en":"The Shin-Marunouchi Building faces the Marunouchi Building across Gyōkō-dōri. Finished in 2007, it replaced a building from 1952. It uses the same idea of a podium about 31 metres high with a tower set back above, so the pair frames the station square like two gateposts. An open terrace on the seventh floor looks out over the red-brick station."}},
  tyjptower: {"k":{"zh":"摩天大楼","en":"Skyscraper"},"y":"2012","a":{"zh":"赫尔穆特·扬","en":"Helmut Jahn"},"h":200,"fl":38,"d":{"zh":"JP塔是日本邮政在旧东京中央邮局原址上建起的办公塔楼。1931年由吉田铁郎设计的老邮局，其临站前广场的白色立面被部分保留下来，成为商场KITTE的入口部分。楼内还有一座展示东京大学收藏品的博物馆。","en":"JP Tower was built by Japan Post on the site of the former Tokyo Central Post Office. Part of the old office’s white facade, designed by Yoshida Tetsurō in 1931 and facing the station square, was kept and now fronts the KITTE shopping centre. The building also houses a museum showing collections of the University of Tokyo."},"x":[{"zh":"商场KITTE于2013年开业","en":"The KITTE shopping centre opened in 2013"}]},
  tytokiwabashi: {"k":{"zh":"摩天大楼","en":"Skyscraper"},"y":"2021","h":212,"d":{"zh":"常盘桥塔是东京站北侧“东京Torch”再开发项目中先建成的一座办公塔楼，2021年落成。它旁边正在建设的Torch Tower计划高约385米，建成后将成为日本最高的建筑。两座塔楼之间留出了一片公共广场。","en":"Tokiwabashi Tower is the first finished office tower of the Tokyo Torch redevelopment just north of Tokyo Station, completed in 2021. Next to it, Torch Tower is under construction and is planned to rise about 385 metres, which would make it the tallest building in Japan. A public plaza lies between the two towers."},"x":[{"zh":"得名于附近日本桥川上的常盘桥","en":"Named after the nearby Tokiwa Bridge over the Nihonbashi River"}]},
  tygranroof: {"k":{"zh":"车站雨棚","en":"Station canopy"},"y":"2013","d":{"zh":"GranRoof是东京站八重洲口的一道白色膜结构长雨棚，2013年建成，连接南北两座GranTokyo塔楼。它所在的位置原是一座旧站房大楼，拆除后改为开阔的站前广场和步行平台，让车站的东面也有了一张新面孔。","en":"GranRoof is the long white membrane canopy over the Yaesu entrance of Tokyo Station, finished in 2013 between the North and South GranTokyo towers. It stands where an older station office block was removed to open up a plaza and a raised walkway, giving the east side of the station a new face."}},
  tynihonbashi: {"k":{"zh":"石拱桥","en":"Stone arch bridge"},"y":"1911","d":{"zh":"日本桥最早建于1603年，是江户时代“五街道”的起点，至今桥中央仍有日本国道的零公里标志。现在的双拱花岗岩桥建于1911年，桥上饰有青铜麒麟和狮子，是国家重要文化财产。1963年首都高速公路从桥的正上方架过。","en":"Nihonbashi was first built in 1603 as the starting point of the five great Edo-period highways, and the zero-kilometre marker of Japan’s national roads is still set in its centre. The present twin-arch granite bridge dates from 1911, decorated with bronze kirin and lions, and is an Important Cultural Property. Since 1963 an elevated expressway has run right above it."},"x":[{"zh":"桥名题字出自最后一位将军德川庆喜之手","en":"The name plaques were written by Tokugawa Yoshinobu, the last shogun"},{"zh":"上方的高速公路计划改走地下","en":"The expressway overhead is planned to move underground"}]},

  /* palace */
  tynijubashi: {"k":{"zh":"桥梁","en":"Bridges"},"y":"1887","d":{"zh":"皇居正门前有两座桥：前面是1887年建成的石造双拱“正门石桥”，后面是跨过二重桥濠的“正门铁桥”。“二重桥”这个名字原本指后面那座桥，因江户时代的木桥建成上下两层桥桁而得名。石桥与后方的伏见橹是东京最经典的风景之一。","en":"Two bridges lead to the main gate of the Imperial Palace: in front, the stone double-arch Seimon Ishibashi of 1887, and behind it the Seimon Tetsubashi over the Nijūbashi Moat. The name Nijūbashi, \"double bridge\", first belonged to the rear bridge, whose Edo-period wooden version had girders in two tiers. The stone bridge with the Fushimi turret behind is a classic Tokyo view."},"x":[{"zh":"新年和天皇诞辰时民众经此进入宫内参贺","en":"The public cross here for the New Year and Emperor’s Birthday greetings"}]},
  tyfushimi: {"k":{"zh":"城郭橹楼","en":"Castle turret"},"d":{"zh":"伏见橹是江户城留存下来的少数几座橹楼之一，两层白墙灰瓦，立在二重桥后方的石垣上，两侧连着长长的多闻橹。相传它是从京都伏见城迁建而来，因此得名。1923年关东大地震后曾拆解重建。","en":"Fushimi-yagura is one of the few surviving turrets of Edo Castle: two storeys of white plaster and grey tile on the stone wall behind Nijūbashi, with long wall-buildings stretching out to each side. By tradition it was moved here from Fushimi Castle in Kyoto, which gave it its name. It was taken apart and rebuilt after the 1923 earthquake."}},
  tyeastgardens: {"k":{"zh":"庭园","en":"Garden"},"y":"1968","d":{"zh":"皇居东御苑是江户城本丸、二之丸和三之丸的旧址，1968年起对公众开放。园内保留着高大的石垣、护城河、大手门和百人番所，本丸高处还有天守台。江户城天守在1657年明历大火中烧毁后再未重建，只剩下这座石台。","en":"The East Gardens occupy the former inner citadel of Edo Castle and have been open to the public since 1968. Massive stone walls, moats, the Ōtemon gate and the Hyakunin-bansho guardhouse remain, and the stone base of the castle keep stands on the high ground. The keep burned in the Great Fire of 1657 and was never rebuilt, leaving only this platform."},"x":[{"zh":"二之丸一带有传统日式回游庭园","en":"The Ninomaru area has a traditional Japanese stroll garden"}]},
  tykokyogaien: {"k":{"zh":"国民公园","en":"National garden"},"d":{"zh":"皇居外苑是皇居正门前的大片广场，铺着白色碎石，草坪上种着约两千棵修剪成形的黑松。这里四周环绕着护城河和石垣，西南角有江户城的樱田门，东侧立着楠木正成的骑马铜像。从这里可以望见二重桥和伏见橹。","en":"Kokyo Gaien is the broad forecourt in front of the Imperial Palace, a plaza of white gravel with lawns planted with about two thousand trimmed black pines. Moats and stone walls surround it, the Sakuradamon gate of Edo Castle stands at its south-west corner, and a bronze equestrian statue of Kusunoki Masashige stands on the east side. It looks towards Nijūbashi and the Fushimi turret."}},
  tydiet: {"k":{"zh":"议会大厦","en":"Parliament building"},"y":"1936","h":65.45,"fl":3,"d":{"zh":"国会议事堂1920年动工，1936年落成，外墙使用了产自日本各地的花岗岩。建筑左右对称：面向正门左侧是众议院，右侧是参议院，中央是一座阶梯金字塔形顶的塔楼，高约65米。它是日本国会所在地，平日可以参观。","en":"The National Diet Building was begun in 1920 and finished in 1936, faced with granite quarried across Japan. It is symmetrical: seen from the front, the House of Representatives is on the left and the House of Councillors on the right, joined by a central tower about 65 metres tall with a stepped pyramid top. It is the seat of Japan’s parliament and offers public tours."}},
  tyakasaka: {"k":{"zh":"宫殿","en":"Palace"},"y":"1909","a":{"zh":"片山东熊","en":"Katayama Tōkuma"},"fl":2,"d":{"zh":"迎宾馆赤坂离宫1909年作为皇太子宫邸建成，是日本唯一的新巴洛克风格宫殿，两翼弧形前楼环抱正面庭院。1974年起改作国宾馆，用来接待外国元首。2009年它成为第一座被指定为国宝的明治时期建筑，现在定期对公众开放参观。","en":"Akasaka Palace was completed in 1909 as the residence of the Crown Prince. It is Japan’s only palace in the Neo-Baroque style, with two curved wings embracing the front court. Since 1974 it has served as the State Guest House for visiting heads of state. In 2009 it became the first Meiji-era building named a National Treasure, and it now opens regularly to visitors."}},
  tyyasukuni: {"k":{"zh":"神社","en":"Shinto shrine"},"y":"1869","d":{"zh":"靖国神社创建于1869年，最初名为东京招魂社，1879年改为现名，祭祀幕末以来在战争中为国家死去的人。参道上依次立着高大的钢制第一鸟居和桧木神门，后方是拜殿与本殿。由于它与战争记忆的关系，这座神社常引起国内外争议。","en":"Yasukuni Shrine was founded in 1869 as Tokyo Shōkonsha and took its present name in 1879. It enshrines those who died for the country in wars since the end of the Edo period. The approach passes a tall steel first torii and a cypress gate before the worship hall and main hall. Its place in the memory of war makes it a subject of debate in Japan and abroad."},"x":[{"zh":"境内一棵染井吉野是东京樱花开花的观测标准木","en":"A cherry tree here is the official sample tree for Tokyo’s blossom forecast"}]},

  /* ginza */
  tywako: {"k":{"zh":"历史建筑","en":"Historic building"},"y":"1932","a":{"zh":"渡边仁","en":"Watanabe Jin"},"d":{"zh":"和光大楼立在银座四丁目十字路口的转角上，1932年落成，弧形的新文艺复兴风格立面上方是一座钟塔。这里早在1894年就建有钟楼，现在的钟塔是银座最有名的象征，整点会响起报时钟声。大楼在二战空袭中幸存下来。","en":"The Wako Building stands on the corner of the Ginza 4-chōme crossing. Completed in 1932, it has a curved Neo-Renaissance facade crowned by a clock tower. A clock tower had stood on this corner since 1894, and today’s is the best-known symbol of Ginza, chiming the hours. The building survived the wartime air raids."}},
  tykabukiza: {"k":{"zh":"剧场","en":"Theatre"},"y":"2013","a":{"zh":"隈研吾","en":"Kuma Kengo"},"d":{"zh":"歌舞伎座是东京上演歌舞伎的专门剧场，1889年首次开幕。现在的第五代剧场于2013年落成，沿用了旧剧场的桃山风格外观：白墙、瓦顶和正门上方巨大的唐破风。剧场后面升起29层的歌舞伎座塔，两者是同一次重建的成果。","en":"Kabuki-za is Tokyo’s dedicated kabuki theatre, first opened in 1889. The present building, the fifth, was completed in 2013 and keeps the Momoyama-style look of its predecessor: white walls, tiled roofs and a great curved karahafu gable over the entrance. The 29-storey Kabuki-za Tower rising behind it came from the same rebuilding."}},
  tykabukizatower: {"k":{"zh":"摩天大楼","en":"Skyscraper"},"y":"2013","h":145,"fl":29,"d":{"zh":"歌舞伎座塔是2013年与新歌舞伎座同时建成的办公塔楼，从剧场屋顶后方升起，高约145米。塔楼低层与剧场相连，五楼有一处屋顶庭园和介绍歌舞伎的展厅，从这里可以近看剧场的瓦屋顶。","en":"Kabuki-za Tower is the office tower built together with the new Kabuki-za in 2013, rising behind the theatre roof to about 145 metres. Its lower floors connect with the theatre, and on the fifth floor a roof garden and a small kabuki gallery let visitors look closely at the theatre’s tiled roofs."}},
  tyshiodomecc: {"k":{"zh":"摩天大楼","en":"Skyscraper"},"y":"2003","fl":43,"d":{"zh":"汐留城市中心是汐留再开发区的一座玻璃幕墙办公塔楼，2003年落成，全日空的总部设在这里。汐留是日本第一条铁路的东京端——旧新桥站的所在地，塔楼前方复原了1872年的车站建筑。","en":"Shiodome City Center is a glass office tower of the Shiodome redevelopment, completed in 2003 and home to the head office of ANA. Shiodome was the Tokyo end of Japan’s first railway, the old Shimbashi Station, and a reconstruction of the 1872 station building stands in front of the tower."},"x":[{"zh":"旧新桥站复原站舍内有铁道历史展示","en":"The rebuilt old Shimbashi Station has a small railway history exhibit"}]},
  tydentsu: {"k":{"zh":"摩天大楼","en":"Skyscraper"},"y":"2002","a":{"zh":"让·努维尔","en":"Jean Nouvel"},"fl":48,"d":{"zh":"这座塔楼由法国建筑师让·努维尔设计，2002年落成，原为电通公司总部。平面呈弯曲的刀刃形，玻璃幕墙上的白色釉点从下往上渐变，让高处的楼身仿佛融进天空。底部的Caretta汐留里有剧场和餐厅。","en":"This tower, designed by the French architect Jean Nouvel and finished in 2002, was built as the head office of Dentsu. Its plan is a curved blade, and the white dots fritted on its glass grade from bottom to top, so the upper floors seem to fade into the sky. Caretta Shiodome at its foot holds a theatre and restaurants."}},
  tyntv: {"k":{"zh":"摩天大楼","en":"Skyscraper"},"y":"2003","a":{"zh":"理查德·罗杰斯","en":"Richard Rogers"},"fl":32,"d":{"zh":"日本电视台塔是日本电视台的总部，2003年落成，由英国建筑师理查德·罗杰斯的事务所设计，外露的钢结构和斜撑是它的特色。塔前平台上有一座由宫崎骏设计的大型机械钟，每天在固定时刻演出一段机关动画。","en":"Nippon Television Tower is the headquarters of the broadcaster Nippon TV, completed in 2003 and designed by the practice of the British architect Richard Rogers, with its exposed steel frame and bracing. On the plaza stands a large mechanical clock designed by Miyazaki Hayao, which puts on a short mechanical show at set times each day."}},
  tytsukiji: {"k":{"zh":"佛教寺院","en":"Buddhist temple"},"y":"1934","a":{"zh":"伊东忠太","en":"Itō Chūta"},"d":{"zh":"筑地本愿寺是净土真宗本愿寺派在东京的据点，1617年创立于浅草附近，1657年大火后迁到这片填海造出的“筑地”。现在的本堂1934年落成，由伊东忠太设计，采用古印度佛教建筑风格，石造外观配圆顶，十分少见。本堂内还有一架管风琴。","en":"Tsukiji Hongan-ji is the Tokyo base of the Hongan-ji branch of Jōdo Shinshū Buddhism. Founded in 1617 near Asakusa, it moved after the fire of 1657 to this reclaimed land, the \"tsukiji\". The present hall of 1934, by Itō Chūta, takes the style of ancient Indian Buddhist architecture, a rare stone building with a dome. Inside is a pipe organ."},"x":[{"zh":"2014年被指定为国家重要文化财产","en":"Named an Important Cultural Property in 2014"}]},

  /* minato */
  tytokyotower: {"k":{"zh":"电视塔","en":"Broadcast tower"},"y":"1958","a":{"zh":"内藤多仲","en":"Naitō Tachū"},"h":333,"d":{"zh":"东京塔1958年落成，高333米，是一座漆成国际橙和白色相间的钢格构塔。塔上有150米的主展望台和250米的顶层展望台。在晴空塔建成之前，它一直是日本最高的构筑物，也是东京最有代表性的风景。","en":"Tokyo Tower was completed in 1958. At 333 metres, this steel lattice tower is painted in bands of international orange and white. It has a main deck at 150 metres and a top deck at 250 metres. Until the Skytree was built it was the tallest structure in Japan, and it remains one of the most familiar sights of Tokyo."},"x":[{"zh":"夜晚以暖橙色的“地标灯光”照亮","en":"Lit at night by the warm orange \"Landmark Light\""},{"zh":"结构设计者内藤多仲被称为“塔博士”","en":"Structural designer Naitō Tachū was known as the \"Doctor of Towers\""}]},
  tyzojoji: {"k":{"zh":"佛教寺院","en":"Buddhist temple"},"y":"1974","d":{"zh":"增上寺是净土宗的大本山，江户时代是德川将军家的菩提寺，境内葬有六位将军。寺内大殿在二战空袭中烧毁，现在的大殿于1974年重建完成。从大殿前望去，东京塔就在背后，古寺与铁塔同框是这里最有名的景色。","en":"Zōjō-ji is a head temple of the Jōdo sect of Buddhism. In the Edo period it was the family temple of the Tokugawa shoguns, and six shoguns are buried here. Its main hall burned in the wartime air raids; the present Daiden was completed in 1974. Seen from the front, the hall with Tokyo Tower rising behind it is one of the city’s best-known views."}},
  tysangedatsu: {"k":{"zh":"寺院山门","en":"Temple gate"},"y":"1622","h":21,"d":{"zh":"三解脱门是增上寺的正门，1622年建成，是东京都心现存最古老的木造建筑之一，为国家重要文化财产。门名的意思是穿过此门便能从贪、嗔、痴三种烦恼中解脱。这座两层朱红色楼门在战火中幸存，上层供奉着释迦三尊和十六罗汉像。","en":"Sangedatsumon is the main gate of Zōjō-ji. Built in 1622, it is one of the oldest wooden buildings in central Tokyo and an Important Cultural Property. Its name means that passing through frees one from three passions: greed, anger and ignorance. The two-storey vermilion gate survived the war, and its upper floor holds statues of the Buddha and sixteen arhats."}},
  tymidtown: {"k":{"zh":"摩天大楼","en":"Skyscraper"},"y":"2007","a":{"zh":"SOM建筑设计事务所","en":"Skidmore, Owings & Merrill"},"h":248,"fl":54,"d":{"zh":"东京中城大厦是六本木东京中城的主楼，2007年落成，高248米，下层是办公室，顶部几层是酒店。东京中城建在原防卫厅的旧址上，塔楼北面是大片绿地和公园。园区内还有三得利美术馆和安藤忠雄设计的21_21 DESIGN SIGHT。","en":"Midtown Tower is the main building of Tokyo Midtown in Roppongi, finished in 2007 at 248 metres, with offices below and a hotel on its top floors. Tokyo Midtown stands on the former site of the Defense Agency, with a large garden and park to the north of the tower. The complex also holds the Suntory Museum of Art and 21_21 DESIGN SIGHT by Andō Tadao."}},
  tyroppongimori: {"k":{"zh":"摩天大楼","en":"Skyscraper"},"y":"2003","a":{"zh":"KPF建筑事务所","en":"Kohn Pedersen Fox"},"h":238,"fl":54,"d":{"zh":"六本木新城森大厦是六本木新城的核心，2003年落成，高238米。塔顶的52、53层设有展望台“东京城市观景”和森美术馆，一座以当代艺术为主的美术馆被放在了城市的最高处之一。大厦底部向外张开，与周围的广场和街道相连。","en":"Roppongi Hills Mori Tower is the centrepiece of Roppongi Hills, completed in 2003 at 238 metres. Its 52nd and 53rd floors hold the Tokyo City View observation deck and the Mori Art Museum, placing a museum of contemporary art near the top of the city. The tower flares out at its base to meet the surrounding plazas and streets."}},
  tyazabudai: {"k":{"zh":"摩天大楼","en":"Skyscraper"},"y":"2023","a":{"zh":"佩里·克拉克建筑事务所","en":"Pelli Clarke & Partners"},"h":325,"fl":64,"d":{"zh":"麻布台之丘森JP塔是麻布台之丘的主楼，2023年落成，高约325米，超过大阪的阿倍野HARUKAS成为日本最高的建筑。玻璃塔身四面带有柔和的弧度，向上逐渐收细，顶部轻轻收拢。它与东京塔隔街相望。","en":"Azabudai Hills Mori JP Tower is the main tower of Azabudai Hills, completed in 2023 at about 325 metres. It overtook Osaka’s Abeno Harukas as the tallest building in Japan. The glass tower curves gently on every side and tapers softly towards its top. It stands within sight of Tokyo Tower."},"x":[{"zh":"低层部分由托马斯·赫斯维克设计","en":"The low-rise buildings were designed by Thomas Heatherwick"}]},
  tytoranomon: {"k":{"zh":"摩天大楼","en":"Skyscraper"},"y":"2014","a":{"zh":"日本设计","en":"Nihon Sekkei"},"h":247,"fl":52,"d":{"zh":"虎之门之丘森大厦2014年落成，高247米，是虎之门之丘建成的第一座塔楼。这座楼最特别的地方在于城市干道环状二号线从它的地下隧道中穿过，道路与建筑合为一体。塔楼四角圆润，顶部几层是酒店。","en":"Toranomon Hills Mori Tower was finished in 2014 at 247 metres, the first tower of Toranomon Hills. Its most unusual feature is that the Loop Road No. 2 artery runs through a tunnel beneath it, so the road and the building were built as one. The tower has rounded corners, and a hotel occupies its top floors."}},
  tytoranomonst: {"k":{"zh":"摩天大楼","en":"Skyscraper"},"y":"2023","a":{"zh":"OMA建筑事务所","en":"OMA"},"h":266,"fl":49,"d":{"zh":"虎之门之丘车站大厦2023年落成，高约266米，由OMA设计，与地铁日比谷线的虎之门之丘站直接相连。塔顶几层是名为TOKYO NODE的活动与展览空间，顶部的玻璃盒子和屋顶花园是它的标志，在那里可以俯看东京塔方向的城市。","en":"Toranomon Hills Station Tower, designed by OMA and completed in 2023, rises about 266 metres and connects directly to Toranomon Hills Station on the Hibiya Line. Its top floors hold TOKYO NODE, a space for events and exhibitions. The glass box at the top and its roof garden, with views towards Tokyo Tower, are its signature."}},

  /* asakusa */
  tyskytree: {"k":{"zh":"电视塔","en":"Broadcast tower"},"y":"2012","a":{"zh":"日建设计","en":"Nikken Sekkei"},"h":634,"d":{"zh":"东京晴空塔2012年开业，高634米，是世界最高的电视塔。塔身底部是三角形，向上逐渐变成圆形，在350米和450米处设有两层展望台。634的日语读音近似“武藏”，即东京一带的古国名。塔中央的混凝土心柱借鉴了五重塔的减震思路。","en":"Tokyo Skytree opened in 2012. At 634 metres it is the world’s tallest broadcasting tower. Its plan changes from a triangle at the base to a circle higher up, with observation decks at 350 and 450 metres. The number 634 can be read as \"Musashi\", the old name of the province around Tokyo. A concrete core column inside borrows the damping idea of pagodas."},"x":[{"zh":"塔身颜色“晴空白”取自传统的淡蓝白色","en":"Its colour, \"Skytree White\", is based on a traditional pale indigo"},{"zh":"夜间轮流点亮淡蓝色“粹”和紫色“雅”","en":"At night it alternates pale-blue \"Iki\" and purple \"Miyabi\" lighting"}]},
  tysolamachi: {"k":{"zh":"商业设施","en":"Shopping complex"},"y":"2012","d":{"zh":"东京晴空街道是与晴空塔同时开业的大型商业设施，沿着塔脚东西延伸，共同组成“东京晴空塔城”。这里有数百家商店和餐厅，还有墨田水族馆和一座天象馆。从商场的露台上可以仰望近在眼前的晴空塔。","en":"Tokyo Solamachi is the large shopping complex that opened with the Skytree in 2012, stretching east and west along the foot of the tower as part of Tokyo Skytree Town. It holds several hundred shops and restaurants, the Sumida Aquarium and a planetarium. Its terraces look straight up at the tower overhead."}},
  tysolamachieast: {"k":{"zh":"办公大楼","en":"Office tower"},"y":"2012","d":{"zh":"东京晴空塔东塔是晴空塔城东端的一座办公塔楼，2012年随整个项目一同建成。它的低层属于晴空街道商场，高层是办公室，顶部还有餐厅楼层。站在这里向西望去，634米的晴空塔就在不远处拔地而起。","en":"Tokyo Skytree East Tower is the office tower at the eastern end of Skytree Town, completed with the rest of the development in 2012. Its lower floors belong to the Solamachi shopping complex and its upper floors hold offices, with restaurant floors near the top. Looking west from here, the 634-metre Skytree rises just a short distance away."}},
  tykaminarimon: {"k":{"zh":"寺院山门","en":"Temple gate"},"y":"1960","h":11.7,"d":{"zh":"雷门是浅草寺的总门，正式名称为“风雷神门”，左右分别供奉风神和雷神像。门中央悬挂着巨大的红色灯笼，高约3.9米，重约700公斤。旧门在江户时代末期烧毁，现在的雷门是1960年由松下幸之助捐资重建的。","en":"Kaminarimon is the outer gate of Sensō-ji, formally the Fūraijinmon, with statues of Fūjin, the god of wind, and Raijin, the god of thunder, on either side. A huge red lantern about 3.9 metres tall and weighing some 700 kilograms hangs in its centre. The old gate burned late in the Edo period; the present one was rebuilt in 1960 with a gift from Matsushita Kōnosuke."}},
  tyhozomon: {"k":{"zh":"寺院山门","en":"Temple gate"},"y":"1964","d":{"zh":"宝藏门是浅草寺的山门，位于仲见世商店街的尽头，两层朱红色楼门，两侧立着仁王像，过去也称仁王门。门的上层收藏着寺院的经卷等宝物，因此得名。门背面挂着一对巨大的草鞋，由山形县村山市的民众制作献纳。现门建于1964年。","en":"Hōzōmon is the inner gate of Sensō-ji at the end of Nakamise. The two-storey vermilion gate is guarded by two Niō statues and was once called the Niōmon. Its upper floor stores the temple’s sutras and other treasures, which gave it its name. A pair of giant straw sandals made by people of Murayama in Yamagata hangs on its back. The present gate dates from 1964."}},
  tysensoji: {"k":{"zh":"佛教寺院","en":"Buddhist temple"},"y":"1958","d":{"zh":"浅草寺是东京最古老的寺院，相传628年两兄弟在隅田川中捞到一尊观音像，由此创建。本堂又称观音堂，在1945年空袭中烧毁，1958年用钢筋混凝土重建，保留了陡峭的大屋顶和朱红色立柱。2010年屋顶换成了钛金属瓦。","en":"Sensō-ji is Tokyo’s oldest temple. By tradition it was founded in 628, after two brothers fishing in the Sumida River found a statue of Kannon in their net. The main hall, or Kannon-dō, burned in the 1945 air raids and was rebuilt in concrete in 1958, keeping its steep sweeping roof and vermilion columns. In 2010 the roof was re-tiled in titanium."}},
  typagoda: {"k":{"zh":"佛塔","en":"Pagoda"},"y":"1973","h":53,"d":{"zh":"浅草寺五重塔原塔在1945年空袭中烧毁，1973年在宝藏门西侧重建，位置也从原来的东侧移了过来。塔高约53米（含基座），朱红色塔身配五层瓦顶和相轮。塔的最上层安奉着从斯里兰卡迎来的佛舍利。","en":"Sensō-ji’s five-storey pagoda burned in the 1945 air raids and was rebuilt in 1973 on the west side of the Hōzōmon, having stood on the east side before. It is about 53 metres tall including its base, with a vermilion body, five tiled roofs and a tall finial. Relics of the Buddha brought from Sri Lanka are kept on its top floor."}},
  tynakamise: {"k":{"zh":"商店街","en":"Shopping street"},"d":{"zh":"仲见世是从雷门通往宝藏门的参道商店街，长约250米，两侧排列着近九十家小店，出售人形烧、仙贝、扇子和各种纪念品。它的起源可以追溯到江户时代，当时附近居民获准在参道上摆摊，是日本最古老的商店街之一。","en":"Nakamise is the shopping street on the temple approach from Kaminarimon to Hōzōmon. About 250 metres long, it is lined with some ninety small shops selling ningyō-yaki cakes, rice crackers, fans and souvenirs. Its origins go back to the Edo period, when local people were allowed to set up stalls along the approach, making it one of Japan’s oldest shopping streets."}},
  tyasahihall: {"k":{"zh":"啤酒厅","en":"Beer hall"},"y":"1989","a":{"zh":"菲利普·斯塔克","en":"Philippe Starck"},"d":{"zh":"这座啤酒厅位于隅田川东岸，1989年落成，由法国设计师菲利普·斯塔克设计。黑色花岗岩外墙的建筑呈上宽下窄的倒梯形，屋顶上横卧着一个巨大的金色火焰雕塑，据说象征着燃烧的热情。它与旁边的塔楼一起，是浅草对岸最显眼的风景。","en":"This beer hall on the east bank of the Sumida River was completed in 1989 to a design by the French designer Philippe Starck. The black granite building widens towards the top like an upside-down trapezoid, and a huge golden flame sculpture lies on its roof, said to stand for a burning passion. With the tower beside it, it is the most eye-catching sight across the river from Asakusa."}},
  tyasahitower: {"k":{"zh":"办公大楼","en":"Office tower"},"y":"1989","d":{"zh":"这座塔楼是隅田川东岸一家啤酒公司的总部，1989年与旁边的金色火焰啤酒厅同时落成。琥珀色的玻璃塔身配上白色的顶部，整体就像一杯满上泡沫的啤酒。它与晴空塔和金色火焰一起，常常出现在从浅草望向对岸的照片里。","en":"This tower is the head office of a brewery on the east bank of the Sumida, completed in 1989 together with the golden-flame beer hall beside it. Its amber glass body and white top make it look like a glass of beer with a head of foam. With the Skytree and the golden flame, it appears in many photos taken across the river from Asakusa."}},

  /* shibuya */
  tyscramble: {"k":{"zh":"摩天大楼","en":"Skyscraper"},"y":"2019","h":230,"fl":47,"d":{"zh":"涩谷SCRAMBLE SQUARE建在涩谷站正上方，2019年开业，高约230米，是涩谷最高的建筑。外立面设计由日建设计与隈研吾、妹岛和世等建筑师合作完成。楼顶的开放式展望台“SHIBUYA SKY”，可以俯瞰脚下的十字路口和远处的富士山。","en":"Shibuya Scramble Square rises right above Shibuya Station. Opened in 2019 at about 230 metres, it is the tallest building in Shibuya, its facades designed by Nikken Sekkei with architects including Kuma Kengo and Sejima Kazuyo. The open-air rooftop deck, Shibuya Sky, looks straight down on the famous crossing and, on clear days, as far as Mount Fuji."}},
  tymeijiotorii: {"k":{"zh":"鸟居","en":"Torii gate"},"y":"1975","h":12,"d":{"zh":"明治神宫大鸟居立在北参道与南参道交会处，高12米，是日本最大的木造明神鸟居之一。1920年的初代大鸟居在1966年遭雷击损坏，现在的鸟居于1975年重建，所用的扁柏取自台湾丹大山，树龄约一千五百年。","en":"The great torii of Meiji Jingū stands where the north and south approaches meet. Twelve metres high, it is one of the largest wooden torii of its style in Japan. The original gate of 1920 was damaged by lightning in 1966, and the present one was raised in 1975, made of cypress from Mount Dandai in Taiwan that was about 1,500 years old."}},
  tyyoyogi1: {"k":{"zh":"体育馆","en":"Arena"},"y":"1964","a":{"zh":"丹下健三","en":"Tange Kenzō"},"d":{"zh":"国立代代木竞技场第一体育馆是为1964年东京奥运会建造的游泳馆，由丹下健三设计。两根钢筋混凝土主塔之间拉起两条主索，屋面从主索垂下，形成两片相互错开的月牙形曲面。这座悬索屋顶是日本现代建筑的代表作，2021年被指定为国家重要文化财产。","en":"The first gymnasium of the Yoyogi National Stadium was built by Tange Kenzō as the swimming hall of the 1964 Tokyo Olympics. Two main cables are strung between two concrete masts, and the roof hangs from them in two offset crescent-shaped curves. This suspension roof is a landmark of modern Japanese architecture and was named an Important Cultural Property in 2021."}},
  tyyoyogi2: {"k":{"zh":"体育馆","en":"Arena"},"y":"1964","a":{"zh":"丹下健三","en":"Tange Kenzō"},"d":{"zh":"第二体育馆是代代木竞技场中较小的圆形场馆，1964年奥运会时用作篮球馆。它的屋顶从一根主柱上盘旋而下，像一枚螺旋形的贝壳，与第一体育馆的双塔悬索屋顶相互呼应。两馆在2021年一同被指定为国家重要文化财产。","en":"The second gymnasium is the smaller, round hall of the Yoyogi complex, used for basketball at the 1964 Olympics. Its roof spirals down from a single mast like a seashell, echoing the twin-mast suspension roof of the first gymnasium. The two halls were named Important Cultural Properties together in 2021."}},

  /* shinjuku */
  tytmg1: {"k":{"zh":"政府大楼","en":"Government building"},"y":"1991","a":{"zh":"丹下健三","en":"Tange Kenzō"},"h":243,"fl":48,"d":{"zh":"东京都厅第一本厅舍1991年落成，由丹下健三设计，高243米。大楼在33层以上分成两座塔楼，花岗岩外墙上的网格图案让人联想到集成电路，也像哥特式教堂。两座塔楼的45层都设有免费展望台，在1993年之前它是日本最高的建筑。","en":"Tokyo Metropolitan Government Building No. 1 was completed in 1991 to Tange Kenzō’s design and stands 243 metres tall. Above the 33rd floor it splits into twin towers, and the grid patterns on its granite walls recall both a microchip and a Gothic cathedral. Each tower has a free observation deck on the 45th floor. It was Japan’s tallest building until 1993."},"x":[{"zh":"2024年起外墙上演大型投影秀","en":"Since 2024 a large projection-mapping show has been played on its facade"}]},
  tytmg2: {"k":{"zh":"政府大楼","en":"Government building"},"y":"1991","a":{"zh":"丹下健三","en":"Tange Kenzō"},"h":163,"fl":34,"d":{"zh":"第二本厅舍是东京都厅的第二座大楼，与第一本厅舍同在1991年落成，高约163米。楼身向上逐级退台收分，外墙沿用了与第一本厅舍相同的花岗岩网格。两座大楼之间有通道相连，前方是半圆形的都民广场。","en":"Building No. 2 is the second tower of the Tokyo Metropolitan Government, completed with Building No. 1 in 1991 and about 163 metres tall. It steps back in stages as it rises and wears the same granite grid as its taller neighbour. The two buildings are linked by walkways, with the semicircular Citizens’ Plaza in front."}},
  tycocoon: {"k":{"zh":"摩天大楼","en":"Skyscraper"},"y":"2008","a":{"zh":"丹下都市建筑设计","en":"Tange Associates"},"h":204,"fl":50,"d":{"zh":"东京MODE学园蚕茧大厦2008年落成，高204米，是一座校舍大楼，楼里有三所专门学校。椭圆形的塔身被白色交叉网格包裹，形似一个蚕茧，寓意在这里培养的学生将来破茧而出。它在2008年获得了国际摩天大楼奖。","en":"The Mode Gakuen Cocoon Tower, completed in 2008, is a 204-metre school building that houses three vocational colleges. Its oval body is wrapped in a crossing white lattice that looks like a silk cocoon, a sign of students being nurtured here before they emerge. It won the Emporis Skyscraper Award in 2008."}},
  typarktower: {"k":{"zh":"摩天大楼","en":"Skyscraper"},"y":"1994","a":{"zh":"丹下健三","en":"Tange Kenzō"},"h":235,"fl":52,"d":{"zh":"新宿公园塔1994年落成，高235米，由丹下健三设计。它由三座高度不同的塔楼组合而成，每座顶部都是尖锐的金字塔形玻璃顶，从远处看像一组阶梯状的山峰。顶部楼层是柏悦酒店，因电影《迷失东京》而广为人知。","en":"Shinjuku Park Tower was completed in 1994 to a design by Tange Kenzō and is 235 metres tall. It is made of three towers of different heights, each ending in a sharp glass pyramid, so from afar it reads as a stepped cluster of peaks. The top floors hold the Park Hyatt hotel, made famous by the film Lost in Translation."}},
  tysumitomo: {"k":{"zh":"摩天大楼","en":"Skyscraper"},"y":"1974","a":{"zh":"日建设计","en":"Nikken Sekkei"},"h":210,"fl":52,"d":{"zh":"新宿住友大厦1974年落成，高约210米，是西新宿早期的超高层大楼之一。平面呈三角形，中间是贯通的中庭，因此被称为“三角大楼”。2020年大楼脚下建成了一座覆盖玻璃大屋顶的“三角广场”，可以举办各种活动。","en":"The Shinjuku Sumitomo Building, finished in 1974 at about 210 metres, is one of the early skyscrapers of West Shinjuku. Its plan is a triangle with an atrium running up through the middle, which earned it the nickname \"Triangle Building\". In 2020 a plaza under a great glass roof, the Sankaku Hiroba, opened at its foot as an events space."}},

  /* ueno */
  tytnm: {"k":{"zh":"博物馆","en":"Museum"},"y":"1938","a":{"zh":"渡边仁","en":"Watanabe Jin"},"d":{"zh":"东京国立博物馆本馆1938年落成，由渡边仁设计，是“帝冠样式”的代表：西式钢筋混凝土楼身上覆盖着日式瓦屋顶。东京国立博物馆创立于1872年，是日本最古老的博物馆，本馆展出日本美术。本馆为国家重要文化财产。","en":"The Honkan of the Tokyo National Museum was completed in 1938 to Watanabe Jin’s design. It is a leading example of the \"Imperial Crown\" style: a Western-style concrete building topped with a Japanese tiled roof. Founded in 1872, the museum is the oldest in Japan, and the Honkan shows Japanese art. The building is an Important Cultural Property."}},
  tyuenopark: {"k":{"zh":"公园","en":"Park"},"y":"1873","d":{"zh":"上野公园是1873年日本最早指定的公园之一，原是宽永寺的寺域。园内有东京国立博物馆、国立西洋美术馆等多座博物馆和美术馆，有1882年开园的日本最古老的动物园，还有种满莲花的不忍池。春天约八百株樱花盛开。","en":"Ueno Park was among the first parks named in Japan in 1873, on land that once belonged to Kan’ei-ji temple. It holds the Tokyo National Museum, the National Museum of Western Art and many other museums, Japan’s oldest zoo, opened in 1882, and Shinobazu Pond, covered with lotus in summer. In spring some eight hundred cherry trees bloom here."},"x":[{"zh":"园内有西乡隆盛铜像","en":"A bronze statue of Saigō Takamori stands in the park"},{"zh":"勒·柯布西耶设计的国立西洋美术馆是世界遗产","en":"Le Corbusier’s National Museum of Western Art is a World Heritage Site"}]},
  tyakiba: {"k":{"zh":"街区","en":"District"},"d":{"zh":"秋叶原电器街位于中央通两侧，二战后从买卖收音机零件的黑市发展起来，后来成为日本最大的电器街。如今这里还是动漫、游戏和偶像文化的中心，大楼外墙挂满五颜六色的招牌。周日下午中央通常常变成步行街。","en":"Akihabara Electric Town lines both sides of Chūō-dōri. It grew out of a post-war black market for radio parts into Japan’s largest electronics district. Today it is also a centre of anime, games and idol culture, with buildings covered in colourful signs. On Sunday afternoons Chūō-dōri is often closed to traffic as a pedestrian street."}},
  tytokyodome: {"k":{"zh":"体育场","en":"Stadium"},"y":"1988","a":{"zh":"日建设计、竹中工务店","en":"Nikken Sekkei, Takenaka"},"d":{"zh":"东京巨蛋1988年开业，是日本第一座气承式屋顶的巨蛋球场，昵称“Big Egg”。白色膜屋顶没有任何支柱，全靠馆内比外面稍高的气压撑起。它是读卖巨人队的主场，也常举办演唱会。它的容积常被日本人当作衡量大小的单位。","en":"Tokyo Dome opened in 1988 as Japan’s first stadium with an air-supported roof, nicknamed the \"Big Egg\". Its white membrane roof has no columns at all and is held up by air pressure inside kept slightly higher than outside. It is the home of the Yomiuri Giants and a major concert venue. In Japan its volume is often used as a unit for describing size."}},
  tydomecity: {"k":{"zh":"游乐园","en":"Amusement park"},"y":"1955","d":{"zh":"东京巨蛋城游乐园位于东京巨蛋旁边，前身是1955年开园的后乐园游乐园，2003年改为现名。园中最有名的是没有中心轴的摩天轮，以及从LaQua大楼和摩天轮中间穿过的过山车。它是东京市中心少有的大型游乐设施，晚上灯光很漂亮。","en":"Tokyo Dome City Attractions sits next to Tokyo Dome. It began in 1955 as the Kōrakuen amusement park and took its present name in 2003. Its best-known rides are a Ferris wheel with no hub and a roller coaster that threads through the LaQua building and the wheel itself. It is a rare large amusement park in the middle of Tokyo, bright with lights at night."}},
  tykorakuen: {"k":{"zh":"庭园","en":"Garden"},"d":{"zh":"小石川后乐园是江户时代初期水户德川家的回游式庭园，1629年由德川赖房开始修建，其子德川光圀完成。园名取自范仲淹“先天下之忧而忧，后天下之乐而乐”一句。园内以大泉水为中心，圆月桥倒映水中如满月。","en":"Koishikawa Kōrakuen is an early Edo-period stroll garden of the Mito branch of the Tokugawa family, begun in 1629 by Tokugawa Yorifusa and finished by his son Mitsukuni. Its name comes from a line by the Chinese scholar Fan Zhongyan about enjoying pleasure only after others. The garden centres on a large pond, where the Engetsu-kyō bridge and its reflection make a full moon."},"x":[{"zh":"同时被指定为特别史迹和特别名胜","en":"Designated both a Special Historic Site and a Special Place of Scenic Beauty"}]},

  /* bay */
  tyrainbow: {"k":{"zh":"悬索桥","en":"Suspension bridge"},"y":"1993","h":126,"d":{"zh":"彩虹大桥1993年通车，是横跨东京港、连接芝浦与台场的悬索桥，主跨570米，两座白色主塔高126米。桥面分上下两层：上层是首都高速台场线，下层是一般道路、百合鸥线轨道和人行道。芝浦一侧的引桥绕成一个大环。","en":"Rainbow Bridge opened in 1993, a suspension bridge across Tokyo Harbour between Shibaura and Odaiba. Its main span is 570 metres and its two white towers stand 126 metres tall. It has two decks: the upper carries the Shuto Expressway’s Daiba Route, and the lower carries an ordinary road, the Yurikamome line and footpaths. On the Shibaura side the approach curls round in a large loop."},"x":[{"zh":"下层两侧人行道可以步行过桥","en":"Walkways on the lower deck let people cross on foot"}]},
  tyfujitv: {"k":{"zh":"办公大楼","en":"Office building"},"y":"1997","a":{"zh":"丹下健三","en":"Tange Kenzō"},"d":{"zh":"这座台场的电视台总部大楼1997年落成，由丹下健三设计。两座网格状的楼身之间以空中走廊相连，中间悬着一个直径约32米、外覆钛板的大球体，球内是展望台。它是台场海滨最容易辨认的建筑。","en":"This broadcaster’s headquarters in Odaiba was completed in 1997 to a design by Tange Kenzō. Two lattice-framed blocks are joined by sky corridors, and between them hangs a titanium-clad sphere about 32 metres across that holds an observation deck. It is the most recognisable building on the Odaiba waterfront."}},
  tybigsight: {"k":{"zh":"会展中心","en":"Convention centre"},"y":"1996","d":{"zh":"东京国际展示场又称东京Big Sight，1996年开馆，是日本最大的会展中心。正门的会议楼由四个倒金字塔并排立在细柱上，造型非常醒目。这里每年举办许多大型展会，夏冬两季的同人志即卖会Comiket也在这里举行。","en":"Tokyo International Exhibition Center, known as Tokyo Big Sight, opened in 1996 and is the largest convention centre in Japan. Its entrance building is a row of four upside-down pyramids standing on slender legs, an unmistakable shape. It hosts many big trade fairs each year, including the summer and winter Comiket self-published comics market."}},
  tytoyosu: {"k":{"zh":"批发市场","en":"Wholesale market"},"y":"2018","d":{"zh":"丰洲市场2018年10月开业，取代了已运营八十多年的筑地市场，是东京最大的鲜鱼与蔬果批发市场。市场分成几栋大楼，参观者可以沿着专用通道隔窗观看金枪鱼拍卖。水产仲卸卖场楼的屋顶上有一片绿化庭园。","en":"Toyosu Market opened in October 2018, replacing the Tsukiji market after more than eighty years, and is Tokyo’s main wholesale market for fish, fruit and vegetables. It is split into several large buildings, and visitors can watch the tuna auctions through windows from dedicated walkways. The intermediate-wholesale fish building has a garden on its roof."}},
  tygatebridge: {"k":{"zh":"桁架桥","en":"Truss bridge"},"y":"2012","d":{"zh":"东京门大桥2012年通车，横跨东京港第三航道，主跨440米。由于附近有羽田机场的航线，大桥不能修高塔，又必须为大船留出足够的通航净空，于是采用了钢桁架与箱梁结合的结构。两组桁架的造型像两只相对的恐龙，被称为“恐龙桥”。","en":"Tokyo Gate Bridge opened in 2012 across the Tokyo East Channel, with a main span of 440 metres. Flight paths into Haneda ruled out tall towers, yet big ships needed plenty of clearance, so it uses steel trusses combined with box girders. The two truss humps look like a pair of dinosaurs facing each other, which earned it the nickname \"Dinosaur Bridge\"."},"x":[{"zh":"桥上设有可步行的人行道","en":"A footpath on the bridge is open to walkers"}]},
  tykasaiwheel: {"k":{"zh":"摩天轮","en":"Ferris wheel"},"y":"2001","h":117,"d":{"zh":"钻石与花之大摩天轮位于葛西临海公园，2001年启用，高约117米，开业时是日本最高的摩天轮。转一圈约需17分钟，晴天时可以望见东京湾、都心的高楼甚至富士山。夜晚轮上的灯光会变换出钻石和花朵等图案。","en":"The Diamond and Flower Ferris Wheel in Kasai Rinkai Park opened in 2001. About 117 metres tall, it was the tallest Ferris wheel in Japan when it opened. One turn takes about 17 minutes, and on clear days riders can see Tokyo Bay, the towers of central Tokyo and even Mount Fuji. At night its lights form patterns such as diamonds and flowers."}},
  tykasai: {"k":{"zh":"公园","en":"Park"},"y":"1989","d":{"zh":"葛西临海公园1989年开园，是东京湾边的一座大型海滨公园，有草坪、松林、人工海滩和鸟类保护区。园内的葛西临海水族园由谷口吉生设计，玻璃圆顶下的巨大环形水槽里有成群的金枪鱼游动。公园还有一座观景用的玻璃休息楼。","en":"Kasai Rinkai Park opened in 1989, a large seaside park on Tokyo Bay with lawns, pine woods, man-made beaches and a bird sanctuary. Its aquarium, Tokyo Sea Life Park, was designed by Taniguchi Yoshio: under a glass dome, schools of tuna circle a huge ring-shaped tank. The park also has a glass rest house built for the view."}},
  tydisneyland: {"k":{"zh":"主题公园","en":"Theme park"},"y":"1983","d":{"zh":"东京迪士尼乐园1983年4月开园，位于千叶县浦安市的填海地上，是美国以外的第一座迪士尼主题乐园，由东方乐园公司获授权经营。园区约51公顷，分成多个主题区域，中央是一片环形的河道与湖面。","en":"Tokyo Disneyland opened in April 1983 on reclaimed land in Urayasu, Chiba. It was the first Disney theme park outside the United States and is run by the Oriental Land Company under licence. The park covers about 51 hectares and is divided into several themed lands, with a river circling a lake at its centre."}},
  tydisneysea: {"k":{"zh":"主题公园","en":"Theme park"},"y":"2001","d":{"zh":"东京迪士尼海洋2001年9月开园，与东京迪士尼乐园相邻，以海洋和航海为主题，园内分成多个“港口”区域，中央是一座火山造型的山体。2024年新区域开放后，港口增加到八个。它也由东方乐园公司运营。","en":"Tokyo DisneySea opened in September 2001 next to Tokyo Disneyland. Its theme is the sea and seafaring, and it is laid out as a series of \"ports\" around a mountain shaped like a volcano. A new area opened in 2024, bringing the number of ports to eight. It is also run by the Oriental Land Company."}},

  /* airport */
  tyhnd1: {"k":{"zh":"航站楼","en":"Airport terminal"},"y":"1993","d":{"zh":"羽田机场第1航站楼1993年启用，昵称“Big Bird”，主要供国内航班使用。羽田机场1931年开港，后经多次填海扩建，成为日本最繁忙的机场。航站楼屋顶设有展望台，可以近距离看飞机起降，远处还能望见东京湾。","en":"Haneda Terminal 1 opened in 1993 and is nicknamed \"Big Bird\"; it mainly handles domestic flights. Haneda Airport opened in 1931 and has grown through repeated land reclamation into Japan’s busiest airport. The terminal’s rooftop deck gives close views of take-offs and landings, with Tokyo Bay beyond."}},
  tyhnd2: {"k":{"zh":"航站楼","en":"Airport terminal"},"y":"2004","d":{"zh":"羽田机场第2航站楼2004年启用，位于控制塔的东侧，主要供国内航班使用。2020年航站楼增建了国际线设施，开始同时处理国际航班。航站楼与第1航站楼之间有地下通道相连，屋顶同样设有展望台。","en":"Haneda Terminal 2 opened in 2004 east of the control tower and mainly handles domestic flights. In 2020 an international wing was added, so it now handles international flights as well. An underground passage links it to Terminal 1, and it too has a rooftop observation deck."}},
  tyhnd3: {"k":{"zh":"航站楼","en":"Airport terminal"},"y":"2010","d":{"zh":"羽田机场第3航站楼2010年作为国际线航站楼启用，2020年改为现名。航站楼以波浪形大屋顶覆盖出发大厅，楼内还有一条仿照江户街景的商业街。随着羽田国际航线不断增加，这里成了旅客往来东京最便捷的入口之一。","en":"Haneda Terminal 3 opened in 2010 as the International Terminal and took its present name in 2020. A great wave-shaped roof covers its departure hall, and inside is a shopping street modelled on an Edo-period townscape. As Haneda has added more international routes, it has become one of the most convenient gateways to Tokyo."}},
  tyhndtower: {"k":{"zh":"控制塔","en":"Control tower"},"y":"2010","h":115.7,"d":{"zh":"羽田机场的新控制塔2010年启用，高约116米，是世界上最高的机场控制塔之一。为了配合新建的D跑道，管制员需要看清整个扩大的机场，因此塔身修得又高又细，顶部的管制室像一个玻璃灯笼。它立在第1和第2航站楼之间。","en":"Haneda’s new control tower came into use in 2010 and stands about 116 metres tall, one of the tallest airport control towers in the world. With the new Runway D, controllers needed to see the whole enlarged airport, so the tower was made tall and slender, its cab at the top like a glass lantern. It stands between Terminals 1 and 2."}},
  tysaitamaarena: {"k":{"zh":"体育馆","en":"Arena"},"y":"2000","d":{"zh":"埼玉超级竞技场2000年开馆，位于埼玉新都心。场馆的一大块看台可以整体移动约70米，从而在大型体育赛事和小型演出之间变换场地大小，最大可容纳约3.7万人。2021年东京奥运会的篮球比赛就在这里举行。","en":"Saitama Super Arena opened in 2000 at Saitama-Shintoshin. A huge block of its seating can move about 70 metres as a single piece, changing the hall between a big sports arena and a smaller concert space, with room for up to about 37,000 people. It hosted the basketball events of the Tokyo Olympics in 2021."}},
  tymakuhari: {"k":{"zh":"会展中心","en":"Convention centre"},"y":"1989","a":{"zh":"槙文彦","en":"Maki Fumihiko"},"d":{"zh":"幕张展览馆1989年开馆，由槙文彦设计，位于千叶市海边的幕张新都心。展厅的金属屋顶连成一道起伏的波浪线，旁边还有国际会议厅和活动大厅。东京游戏展每年都在这里举行，过去东京车展也曾长期在此举办。","en":"Makuhari Messe opened in 1989, designed by Maki Fumihiko, in the Makuhari new town by the sea in Chiba City. The metal roofs of its exhibition halls form one long undulating wave, alongside an international conference hall and an event hall. The Tokyo Game Show is held here every year, and for many years the Tokyo Motor Show was too."}},

  /* yokohama */
  tylandmark: {"k":{"zh":"摩天大楼","en":"Skyscraper"},"y":"1993","a":{"zh":"休·斯塔宾斯","en":"Hugh Stubbins"},"h":296,"fl":70,"d":{"zh":"横滨地标大厦1993年落成，高296米，2014年之前一直是日本最高的建筑。花岗岩塔身向上逐渐收细，顶部呈阶梯状。69层的展望台“Sky Garden”可以眺望港口和富士山。大厦脚下保留着1896年建成的旧船坞，改成了下沉广场。","en":"Yokohama Landmark Tower was completed in 1993 and, at 296 metres, was Japan’s tallest building until 2014. Its granite shaft tapers as it rises and ends in a stepped top. The Sky Garden deck on the 69th floor looks over the port and towards Mount Fuji. At its foot an old dry dock of 1896 has been kept as a sunken plaza."},"x":[{"zh":"旧船坞“Dockyard Garden”是国家重要文化财产","en":"The old dock, Dockyard Garden, is an Important Cultural Property"}]},
  tycosmoclock: {"k":{"zh":"摩天轮","en":"Ferris wheel"},"y":"1999","h":112.5,"d":{"zh":"横滨宇宙时钟21是港未来21游乐园里的大摩天轮，高112.5米，轮轴中央装有一面巨大的数字时钟。它最初是为1989年横滨博览会建造的，1999年迁到现址并加高。轮上有60个车厢，夜晚灯光变幻，是港未来夜景的焦点。","en":"Cosmo Clock 21 is the big Ferris wheel of the Cosmo World amusement park in Minato Mirai, 112.5 metres tall, with a giant digital clock in its hub. It was first built for the 1989 Yokohama Exotic Showcase expo and was moved to its present site and made taller in 1999. It has 60 gondolas, and its changing lights are the focus of the Minato Mirai night view."}},
  tyqueens: {"k":{"zh":"摩天大楼","en":"Skyscraper"},"y":"1997","h":172,"fl":36,"d":{"zh":"皇后广场横滨塔A是皇后广场横滨三座塔楼中最高的一座，1997年落成，高约172米。A、B、C三座塔楼的高度依次降低，形成一道朝着海边逐级下降的天际线，与旁边的地标大厦形成呼应。塔楼底部是贯通的商业中庭。","en":"Queen’s Tower A is the tallest of the three towers of Queen’s Square Yokohama, completed in 1997 at about 172 metres. Towers A, B and C step down in height towards the sea, forming a descending skyline that answers the Landmark Tower next door. A long shopping atrium runs through their base."}},
  typacifico: {"k":{"zh":"会展中心","en":"Convention centre"},"y":"1991","d":{"zh":"横滨国际和平会议场（Pacifico横滨）1991年开业，集会议中心、展览馆和酒店于一体，坐落在港未来的海边。其中的酒店大楼呈弧形，形似一张鼓满风的船帆，是横滨港最有代表性的轮廓之一。国立大会堂可以容纳约五千人。","en":"Pacifico Yokohama, opened in 1991, combines a conference centre, exhibition halls and a hotel on the Minato Mirai waterfront. Its hotel building is curved like a sail filled with wind and is one of the best-known shapes of Yokohama harbour. The National Convention Hall seats about five thousand people."}},
  tyredbrick: {"k":{"zh":"历史建筑","en":"Historic buildings"},"y":"1911–1913","a":{"zh":"妻木赖黄","en":"Tsumaki Yorinaka"},"d":{"zh":"横滨红砖仓库原是国家的保税仓库，二号馆1911年建成，一号馆1913年建成，由妻木赖黄设计，红砖墙配铁制阳台。1923年关东大地震时一号馆损毁了一部分。仓库停用多年后，2002年改造为商业和文化设施重新开放。","en":"The Red Brick Warehouses were built as government bonded warehouses: Building No. 2 in 1911 and No. 1 in 1913, designed by Tsumaki Yorinaka, with red-brick walls and iron balconies. Part of No. 1 was destroyed in the 1923 Great Kantō Earthquake. After years out of use, they reopened in 2002 as shops, restaurants and cultural spaces."}},
  tyosanbashi: {"k":{"zh":"客运码头","en":"Passenger terminal"},"y":"2002","a":{"zh":"FOA建筑事务所","en":"Foreign Office Architects"},"d":{"zh":"大栈桥是横滨港的国际客船码头，最早建于1894年。现在的客运大楼2002年落成，由FOA事务所在国际竞赛中胜出设计，整个屋顶是一片起伏的木板和草坪甲板，几乎看不到传统的柱子和楼层。屋顶全天对公众开放，可以眺望港未来的天际线。","en":"Ōsanbashi is Yokohama’s international passenger pier, first built in 1894. The present terminal, completed in 2002, was designed by Foreign Office Architects after winning an international competition. Its whole roof is an undulating deck of timber boards and grass, with hardly a conventional column or floor in sight. The roof is open to the public all day and looks across to the Minato Mirai skyline."}},
  tymarinetower: {"k":{"zh":"观光塔","en":"Observation tower"},"y":"1961","h":106,"d":{"zh":"横滨海洋塔1961年为纪念横滨开港百年而建，高106米，是一座十角形的钢格构塔，位于山下公园旁边。它曾兼作灯塔使用直到2008年，一度被认为是世界上最高的灯塔。塔上的展望台可以俯瞰港口和停泊的冰川丸。","en":"Yokohama Marine Tower was built in 1961 to mark the centenary of the opening of the port of Yokohama. It is a 106-metre decagonal steel lattice tower beside Yamashita Park. It also served as a lighthouse until 2008 and was once counted as the tallest lighthouse in the world. Its observation deck looks over the harbour and the moored Hikawa Maru."}},
  tyhikawamaru: {"k":{"zh":"博物馆船","en":"Museum ship"},"y":"1930","d":{"zh":"冰川丸是1930年在横滨建造的远洋客轮，曾航行于横滨与美国西雅图之间的航线，卓别林也曾乘坐过。二战期间它被用作医院船并幸存下来。1961年起，它作为博物馆船停泊在山下公园旁，2016年被指定为国家重要文化财产。","en":"Hikawa Maru is an ocean liner built in Yokohama in 1930 for the route between Yokohama and Seattle; Charlie Chaplin was among its passengers. During the Second World War it served as a hospital ship and survived. Since 1961 it has been moored beside Yamashita Park as a museum ship, and in 2016 it was named an Important Cultural Property."}},
  tychinatown: {"k":{"zh":"街区","en":"District"},"d":{"zh":"横滨中华街是日本最大的唐人街，在1859年横滨开港后逐渐形成，约五百米见方的街区里聚集了数百家餐馆和商店。街区四周立着十座牌楼，东南西北四座分别以青龙、朱雀、白虎、玄武守护。关帝庙是这里的信仰中心。","en":"Yokohama Chinatown is the largest Chinatown in Japan. It took shape after the port opened in 1859, and several hundred restaurants and shops are packed into an area about 500 metres across. Ten decorated gates stand around the district; the four facing east, south, west and north are guarded by the Azure Dragon, Vermilion Bird, White Tiger and Black Tortoise. The Kanteibyō temple to Guan Yu is its spiritual centre."}},
  tybaybridge: {"k":{"zh":"斜拉桥","en":"Cable-stayed bridge"},"y":"1989","h":172,"d":{"zh":"横滨港湾大桥1989年通车，是横跨横滨港入口的双层斜拉桥，主跨460米，两座H形主塔高172米。上层是首都高速湾岸线，下层的国道357号线于2004年开通。从山下公园和大栈桥看去，它是横滨港最醒目的背景。","en":"Yokohama Bay Bridge opened in 1989 across the entrance of Yokohama harbour. It is a double-deck cable-stayed bridge with a 460-metre main span between two H-shaped towers 172 metres tall. The upper deck carries the Shuto Bayshore Route, and the lower deck, Route 357, opened in 2004. Seen from Yamashita Park and Ōsanbashi, it is the great backdrop of the port."}},
  tytsubasa: {"k":{"zh":"斜拉桥","en":"Cable-stayed bridge"},"y":"1994","h":183,"d":{"zh":"鹤见翼桥1994年通车，承载首都高速湾岸线跨越鹤见航道，主跨510米。它只有一座倒Y形的主塔，高183米，斜拉索排成一个平面从塔顶向两侧展开，像一对张开的翅膀，“翼”的名字由此而来。桥面距海面约57米。","en":"Tsurumi Tsubasa Bridge opened in 1994 to carry the Shuto Bayshore Route over the Tsurumi channel, with a main span of 510 metres. It has a single inverted-Y tower 183 metres tall, and its cables fan out from it in one plane like a pair of spread wings, which gave it the name \"tsubasa\", wing. The road runs about 57 metres above the sea."}},

  /* tyx_central */
  tyforum: {"k":{"zh":"会议与文化中心","en":"Convention and arts centre"},"y":"1996","a":{"zh":"拉斐尔·维诺里","en":"Rafael Viñoly"},"d":{"zh":"东京国际论坛位于有乐町，建在原东京都厅的旧址上，1996年开馆，设计者拉斐尔·维诺里在国际竞赛中胜出。最醒目的是长约207米、形似船身的玻璃大厅，旁边排列着四座大小不同的会堂，其中最大的A会堂约有五千个座位。","en":"Tokyo International Forum stands in Yūrakuchō on the site of the former Tokyo Metropolitan Government offices and opened in 1996. Rafael Viñoly won the international competition for its design. Its best-known part is the Glass Hall, about 207 metres long and shaped like a ship’s hull, beside four halls of different sizes; the largest, Hall A, seats about five thousand people."}},
  tyboj: {"k":{"zh":"历史建筑","en":"Historic building"},"y":"1896","a":{"zh":"辰野金吾","en":"Tatsuno Kingo"},"d":{"zh":"日本银行本店本馆1896年落成，由辰野金吾设计，这位建筑师后来还设计了东京站。石造的新巴洛克式建筑两翼围出一个前院，中央立着一座圆顶。它建在江户时代铸造金币的“金座”旧址上，现为国家重要文化财产。","en":"The main building of the Bank of Japan Head Office was completed in 1896 to a design by Tatsuno Kingo, who later designed Tokyo Station. Its stone wings, in Neo-Baroque style, enclose a forecourt under a central dome. It stands on the site of the Kinza, the gold mint of the Edo period, and is an Important Cultural Property."}},
  tykandamyojin: {"k":{"zh":"神社","en":"Shinto shrine"},"y":"1934","d":{"zh":"神田明神据传创建于730年，1616年迁到现址，被奉为江户的总镇守。现在的社殿是1934年建成的钢筋混凝土建筑，外观仍是传统的朱漆样式。每两年一次的神田祭是江户三大祭之一。神社离秋叶原很近，也受到那里电器商家的崇敬。","en":"Kanda Myōjin is said to have been founded in 730 and moved to its present site in 1616, becoming the guardian shrine of all Edo. The present main hall, built in 1934, is of reinforced concrete but keeps the traditional vermilion form. The Kanda Matsuri, held every other year, is one of the three great festivals of Edo. Being close to Akihabara, the shrine is popular with its electronics shops too."}},
  tynikolai: {"k":{"zh":"东正教主教座堂","en":"Orthodox cathedral"},"y":"1891","d":{"zh":"尼古拉堂正式名称为东京复活主教座堂，1891年建于神田骏河台，以创立日本正教会的圣尼古拉命名。设计出自一位俄国建筑师，由约西亚·康德主持施工。1923年关东大地震时圆顶坍塌，1929年修复完成，现为国家重要文化财产。","en":"Nikolai-dō, properly the Holy Resurrection Cathedral, was built in 1891 at Kanda-Surugadai and is named after St Nicholas of Japan, who founded the Japanese Orthodox Church. It was designed by a Russian architect, with Josiah Conder overseeing the construction. Its dome fell in the 1923 Great Kantō Earthquake and the repairs were finished in 1929. It is an Important Cultural Property."}},
  tyhie: {"k":{"zh":"神社","en":"Shinto shrine"},"y":"1958","d":{"zh":"日枝神社位于赤坂的小山上，江户时代是江户城的镇守神社，1659年迁到现址。社殿在1945年空袭中烧毁，现在的社殿于1958年重建。神社以猴子为神使，每两年举行一次的山王祭是江户的大祭之一。一条参道穿过朱红色的鸟居隧道，另一条设有自动扶梯。","en":"Hie Shrine stands on a hill in Akasaka. In the Edo period it was the guardian shrine of Edo Castle, and it moved to this site in 1659. Its buildings burned in the 1945 air raids, and the main hall was rebuilt in 1958. Monkeys are its messengers. The Sannō Matsuri, held every other year, is one of the great festivals of Edo. One approach runs through a tunnel of red torii, another has escalators."}},
  tykachidoki: {"k":{"zh":"开合桥","en":"Bascule bridge"},"y":"1940","d":{"zh":"胜哄桥1940年建成，位于隅田川入海口附近，中央是一段可以向上开启的双叶式开合桥，两侧各有一跨钢拱。过去桥面会定时升起，让大船通过，1970年以后不再开启。它与永代桥、清洲桥一起在2007年被指定为国家重要文化财产。","en":"Kachidoki Bridge was finished in 1940 near the mouth of the Sumida River. Its centre is a double-leaf bascule span between two steel arches. The leaves were once raised on a timetable to let large ships through, but they have not opened since 1970. Together with the Eitai and Kiyosu bridges, it was named an Important Cultural Property in 2007."},"x":[{"zh":"桥名来自纪念日俄战争胜利而开设的“胜哄渡口”","en":"Named after the Kachidoki ferry, opened to celebrate a victory in the Russo-Japanese War"}]},
  tyeitai: {"k":{"zh":"钢拱桥","en":"Steel arch bridge"},"y":"1926","d":{"zh":"永代桥最早在1698年架设于隅田川上。现在的钢拱桥是1923年关东大地震后东京复兴工程的一部分，1926年建成。2007年它与清洲桥、胜哄桥一起被指定为国家重要文化财产，夜晚桥身以蓝色灯光照明。","en":"Eitai Bridge was first built across the Sumida in 1698. The present steel arch bridge was finished in 1926 as part of the rebuilding of Tokyo after the 1923 Great Kantō Earthquake. In 2007 it became an Important Cultural Property together with the Kiyosu and Kachidoki bridges, and at night it is lit in blue."}},
  tykiyosu: {"k":{"zh":"悬索桥","en":"Suspension bridge"},"y":"1928","d":{"zh":"清洲桥1928年建成，是关东大地震后复兴工程中架设的一座自锚式悬索桥，据说以德国科隆的一座莱茵河吊桥为原型。桥名取自它所连接的两岸地名清住町和中洲。线条柔和的清洲桥常与下游刚劲的永代桥对比，2007年被指定为国家重要文化财产。","en":"Kiyosu Bridge was finished in 1928 during the rebuilding after the Great Kantō Earthquake. It is a self-anchored suspension bridge, said to be modelled on a Rhine bridge in Cologne. Its name joins those of the two neighbourhoods it linked, Kiyosumi and Nakasu. Its gentle curves are often contrasted with the sturdier Eitai Bridge downstream. It became an Important Cultural Property in 2007."}},
  tyhamarikyu: {"k":{"zh":"日本庭园","en":"Japanese garden"},"d":{"zh":"滨离宫恩赐庭园是江户时代德川将军家的庭园，这片海边原是将军的猎鹰场，后来成为将军的别邸“滨御殿”。明治以后它成为皇室的离宫，1945年赐给东京市，次年对外开放。园中的潮入之池引入东京湾的海水，水位随潮汐涨落，池中小岛上建有中岛御茶屋。","en":"Hama-rikyū was a garden of the Tokugawa shoguns. This shore was first a falconry ground and later became the shogun’s villa, Hama Goten. After the Meiji Restoration it was an imperial detached palace; it was given to the city of Tokyo in 1945 and opened the following year. Its Shioiri Pond takes in seawater from Tokyo Bay and rises and falls with the tide, and the Nakajima teahouse stands on an island in it."}},
  tyedotokyo: {"k":{"zh":"博物馆","en":"Museum"},"y":"1993","a":{"zh":"菊竹清训","en":"Kikutake Kiyonori"},"d":{"zh":"江户东京博物馆1993年开馆，位于两国国技馆旁边，由新陈代谢派建筑师菊竹清训设计。巨大的展馆被四根粗壮的柱脚高高架起，造型取自传统的高床式仓库，下方是开放的广场。馆内按原尺寸复原了半座日本桥，展示江户和东京四百年来的城市生活。","en":"The Edo-Tokyo Museum opened in 1993 next to the Ryōgoku Kokugikan. It was designed by Kikutake Kiyonori, one of the Metabolist architects. Its huge exhibition block is lifted high on four massive legs over an open plaza, a shape taken from traditional raised storehouses. Inside, a full-size half of the old Nihonbashi bridge leads into displays of four hundred years of city life in Edo and Tokyo."}},
  tykokugikan: {"k":{"zh":"相扑场馆","en":"Sumo arena"},"y":"1985","d":{"zh":"两国国技馆是大相扑的主场馆，1985年在两国站旁落成，约有一万一千个座位。每年六场大相扑本场所中的三场（一月、五月和九月）在这里举行。场馆上方是传统样式的绿色大屋顶，馆内设有相扑博物馆。2021年东京奥运会的拳击比赛也在这里进行。","en":"Ryōgoku Kokugikan is the home of sumo, opened in 1985 beside Ryōgoku Station with about 11,000 seats. Three of the six grand sumo tournaments each year, in January, May and September, are held here. A green roof in traditional style covers the hall, and a sumo museum is inside. It also hosted the boxing events of the Tokyo Olympics in 2021."}},

  /* tyx_west */
  tycrossing: {"k":{"zh":"十字路口","en":"Road crossing"},"d":{"zh":"涩谷十字路口位于涩谷站八公口前，信号灯变绿时所有方向的车辆同时停下，行人可以从四面八方甚至斜着穿过。高峰时一次绿灯就有上千人同时过街，它常被称为世界上最繁忙的人行横道之一，四周大楼上的大屏幕让这里昼夜通明。","en":"Shibuya Crossing lies in front of the Hachikō exit of Shibuya Station. When the lights change, all traffic stops at once and pedestrians cross in every direction, even diagonally. At busy times well over a thousand people cross on a single green light, and it is often called one of the busiest crossings in the world. Big video screens on the buildings around it keep it bright day and night."},"x":[{"zh":"旁边有忠犬八公的铜像","en":"The statue of the faithful dog Hachikō stands nearby"}]},
  tymeijijingu: {"k":{"zh":"神社","en":"Shinto shrine"},"y":"1920","d":{"zh":"明治神宫建于1920年，祭祀明治天皇与昭宪皇太后。环绕神社的约70公顷森林是人工种出来的：当年从全国各地献来约十万棵树，按百年后能自然更新的设想栽种，如今已长成都市中心茂密的树林。主殿在空袭中烧毁，1958年重建。","en":"Meiji Jingū was built in 1920 to enshrine Emperor Meiji and Empress Shōken. The forest of about 70 hectares around it was planted by hand: some 100,000 trees donated from all over Japan were set out so the woods would renew themselves over a century, and today they form a dense forest in the city centre. The main halls burned in the air raids and were rebuilt in 1958."},"x":[{"zh":"新年初诣时是日本参拜人数最多的神社之一","en":"At New Year it draws more visitors than almost any other shrine in Japan"}]},
  tystadium: {"k":{"zh":"体育场","en":"Stadium"},"y":"2019","a":{"zh":"隈研吾","en":"Kuma Kengo"},"d":{"zh":"国立竞技场2019年建成，是2020年东京奥运会（2021年举行）的主体育场，建在1958年旧国立竞技场的原址上。外圈层层出挑的屋檐使用了来自日本全部47个都道府县的木材，屋檐上种满绿植，整体高度压得很低，以融入周围的神宫外苑。","en":"The Japan National Stadium was completed in 2019 as the main venue of the Tokyo 2020 Olympics, held in 2021, on the site of the old National Stadium of 1958. Its layered eaves use timber from all 47 prefectures of Japan and are planted with greenery, and the whole stadium is kept low to blend into the Jingū Gaien park around it."}},
  tygyoen: {"k":{"zh":"国民公园","en":"National garden"},"y":"1906","d":{"zh":"新宿御苑原是江户时代高远藩内藤家的宅邸，1906年成为皇室庭园，1949年起向公众开放。园区约58公顷，融合了法式规整园、英式风景园和日本传统庭园三种风格，还有一座大温室。春天约千株樱花盛开，是东京最著名的赏樱地之一。","en":"Shinjuku Gyoen was the Edo-period estate of the Naitō family, lords of Takatō, before becoming an imperial garden in 1906. It has been open to the public since 1949. Its 58 hectares combine a French formal garden, an English landscape garden and traditional Japanese gardens, with a large greenhouse. In spring about a thousand cherry trees make it one of Tokyo’s best-known places for hanami."}},
  tymetgym: {"k":{"zh":"体育馆","en":"Sports arena"},"y":"1990","a":{"zh":"槙文彦","en":"Maki Fumihiko"},"d":{"zh":"东京体育馆位于千驮谷，现在的建筑由槙文彦设计，1990年落成。主竞技场的不锈钢屋顶曲线流畅，常被比作一顶头盔，旁边的室内游泳池和副竞技场以广场相连。原址上的旧体育馆曾承办1964年东京奥运会的体操比赛，2021年东京奥运会的乒乓球比赛也在这里举行。","en":"Tokyo Metropolitan Gymnasium stands in Sendagaya. The present buildings, designed by Maki Fumihiko, were completed in 1990. The main arena’s smooth stainless-steel roof is often likened to a helmet, and an indoor pool and a sub-arena sit beside it around a plaza. The earlier gymnasium on this site hosted gymnastics at the 1964 Tokyo Olympics, and the table tennis of the Tokyo Olympics in 2021 was held here."}},
  tyoperacity: {"k":{"zh":"摩天大楼","en":"Skyscraper"},"y":"1996","h":234,"fl":54,"d":{"zh":"东京歌剧城塔楼位于西新宿的初台，1996年落成，高约234米，地上54层。塔楼的低层部分设有以作曲家武满彻命名的音乐厅和一座美术馆，旁边就是上演歌剧和芭蕾的新国立剧场，三者合成一个大型文化综合体。","en":"Tokyo Opera City Tower stands at Hatsudai, west of Shinjuku. Completed in 1996, it rises about 234 metres over 54 floors. Its low-rise part holds a concert hall named after the composer Takemitsu Tōru and an art gallery, and next door is the New National Theatre for opera and ballet, together forming a large cultural complex."}},
  tydocomo: {"k":{"zh":"摩天大楼","en":"Skyscraper"},"y":"2000","d":{"zh":"NTT都科摩代代木大厦2000年落成，位于新宿站南侧，是东京西部天际线上最好认的高楼之一。它的塔顶层层收进，上面立着细长的尖顶，常让人联想到纽约的帝国大厦。塔顶下方四面各有一座大钟，楼内大部分空间用于通信设备。","en":"The NTT Docomo Yoyogi Building was finished in 2000 just south of Shinjuku Station and is one of the easiest towers to pick out on the western skyline. Its top steps back in stages under a slender spire, often compared with the Empire State Building in New York. A large clock sits on each face below the top, and much of the building holds telecommunications equipment."}},
  tymitsui: {"k":{"zh":"摩天大楼","en":"Skyscraper"},"y":"1974","h":225,"fl":55,"d":{"zh":"新宿三井大厦1974年落成，高约225米，地上55层，直到1978年阳光60落成前一直是日本最高的建筑。深色的外墙露出钢结构的格子，塔楼脚下是一个下沉式广场。2015年屋顶加装了大型阻尼装置，以减轻长周期地震动造成的晃动。","en":"The Shinjuku Mitsui Building was completed in 1974. At about 225 metres and 55 floors, it was the tallest building in Japan until Sunshine 60 opened in 1978. Its dark facade shows the grid of its steel frame, and a sunken plaza lies at its foot. In 2015 large dampers were added on the roof to reduce swaying in long, slow earthquake motions."}},
  tykeioplaza: {"k":{"zh":"酒店塔楼","en":"Hotel tower"},"y":"1971","h":178,"fl":47,"d":{"zh":"京王广场大饭店本馆1971年开业，高178米，地上47层，是西新宿副都心的第一座摩天大楼，落成时也是日本最高的建筑。白色的本馆旁边是1980年增建的南馆。西新宿的超高层街区建在旧淀桥净水场的原址上，这座楼是其中的第一座。","en":"The Keio Plaza Hotel opened in 1971. Its main tower, 178 metres tall with 47 floors, was the first skyscraper of the new Nishi-Shinjuku centre and the tallest building in Japan at the time. The south tower beside it was added in 1980. The skyscraper district of Nishi-Shinjuku was built on the site of the old Yodobashi water purification plant, and this was its first tower."}},
  tycamii: {"k":{"zh":"清真寺","en":"Mosque"},"y":"2000","d":{"zh":"东京清真寺位于涩谷区代代木上原附近，前身是1938年由来自俄国的鞑靼移民建造的清真寺。老寺因老化在1986年拆除，在土耳其的支持下于2000年以奥斯曼风格重建，主穹顶旁立着一座细高的宣礼塔。它是日本最大的清真寺之一，平时也向参观者开放。","en":"Tokyo Camii stands near Yoyogi-Uehara in Shibuya. Its forerunner was a mosque built in 1938 by Tatar immigrants from Russia. The old building was pulled down in 1986 because of its age, and with support from Turkey the mosque was rebuilt in Ottoman style in 2000, a central dome beside a slender minaret. It is one of the largest mosques in Japan and welcomes visitors."}},
  tyyebisu: {"k":{"zh":"摩天大楼","en":"Skyscraper"},"y":"1994","h":167,"fl":40,"d":{"zh":"惠比寿花园广场塔楼1994年落成，高约167米，地上40层，是惠比寿花园广场的中心建筑。整个街区建在一座老啤酒厂的旧址上，惠比寿这个地名就来自当年在这里酿造的啤酒。广场上有一座法式城堡风格的餐厅建筑，附近还有东京都写真美术馆。","en":"Yebisu Garden Place Tower was completed in 1994, about 167 metres tall with 40 floors, at the heart of Yebisu Garden Place. The whole complex stands on the site of an old brewery, and the name of the Ebisu district itself comes from the beer once brewed here. A restaurant building in the style of a French château faces the plaza, and the Tokyo Photographic Art Museum is close by."}},

  /* tyx_north */
  tynact: {"k":{"zh":"美术馆","en":"Art museum"},"y":"2007","a":{"zh":"黑川纪章","en":"Kurokawa Kishō"},"d":{"zh":"国立新美术馆2007年在六本木开馆，由黑川纪章设计，是他最后的大型作品之一。它没有自己的馆藏，专门举办各类展览，展览空间在日本名列前茅。正面是一道起伏的玻璃幕墙，中庭里立着两座倒圆锥形的混凝土体，顶部分别是餐厅和咖啡馆。","en":"The National Art Center, Tokyo opened in Roppongi in 2007, designed by Kurokawa Kishō as one of his last major works. It has no collection of its own and is devoted to exhibitions, with one of the largest exhibition spaces in Japan. Its front is a rippling glass wall, and inside the atrium two inverted concrete cones carry a restaurant and a café on their tops."}},
  tysunshine60: {"k":{"zh":"摩天大楼","en":"Skyscraper"},"y":"1978","h":239.7,"fl":60,"d":{"zh":"阳光60大厦1978年在池袋落成，高约240米，地上60层，直到1985年都是亚洲最高的建筑，在日本则一直保持最高纪录到东京都厅落成。它是“阳光城”综合设施的核心，这片土地原是巢鸭监狱的旧址。60层设有展望台。","en":"Sunshine 60 was completed in Ikebukuro in 1978, about 240 metres tall with 60 floors. It was the tallest building in Asia until 1985 and the tallest in Japan until the Tokyo Metropolitan Government Building was finished. It is the heart of the Sunshine City complex, built on the site of the former Sugamo Prison. An observation deck occupies the 60th floor."}},
  tystmary: {"k":{"zh":"天主教主教座堂","en":"Catholic cathedral"},"y":"1964","a":{"zh":"丹下健三","en":"Tange Kenzō"},"d":{"zh":"东京圣玛利亚主教座堂是天主教东京总教区的主教座堂，1964年落成，由丹下健三设计。八片覆着不锈钢板的双曲抛物面薄壳从菱形平面升起，在屋顶交会成十字形的天窗。旁边独立的钟塔高六十多米。原来的木造教堂在1945年空袭中烧毁。","en":"St Mary’s Cathedral is the cathedral of the Catholic Archdiocese of Tokyo, completed in 1964 to a design by Tange Kenzō. Eight hyperbolic paraboloid shells clad in stainless steel rise from a diamond-shaped plan and meet in a cross-shaped skylight over the roof. A separate bell tower stands over 60 metres tall. The earlier wooden cathedral burned in the air raids of 1945."}},
  tywesternart: {"k":{"zh":"美术馆","en":"Art museum"},"y":"1959","a":{"zh":"勒·柯布西耶","en":"Le Corbusier"},"d":{"zh":"国立西洋美术馆1959年开馆，本馆由勒·柯布西耶设计，是他在东亚唯一的作品，为收藏从法国归还的松方收藏而建。方形的展馆架在底层架空柱上，展厅围绕中央大厅螺旋展开。2016年本馆作为柯布西耶建筑作品的一部分列入世界文化遗产，前庭陈列着罗丹的雕塑。","en":"The National Museum of Western Art opened in 1959. Its main building was designed by Le Corbusier, his only work in East Asia, to house the Matsukata Collection returned by France. The square gallery block stands on pilotis, its rooms spiralling round a central hall. In 2016 it was inscribed as part of the World Heritage listing of his architectural work. Rodin sculptures stand in the forecourt."}},
  tytoshogu: {"k":{"zh":"神社","en":"Shinto shrine"},"y":"1651","d":{"zh":"上野东照宫祭祀德川家康，现在的社殿是1651年由三代将军德川家光重建的，金碧辉煌，被称为“金色殿”。它躲过了地震和战火，保存至今，社殿为国家重要文化财产。参道两旁排列着各地大名献纳的石灯笼和铜灯笼。","en":"Ueno Tōshōgū enshrines Tokugawa Ieyasu. Its present buildings were rebuilt in 1651 by the third shogun, Tokugawa Iemitsu, and are so richly gilded that the main shrine is called the Golden Hall. They have survived earthquakes and war and are Important Cultural Properties. The approach is lined with stone and bronze lanterns given by feudal lords."}},
  tykiyomizu: {"k":{"zh":"佛堂","en":"Buddhist hall"},"y":"1631","d":{"zh":"清水观音堂是宽永寺的一座佛堂，1631年仿照京都清水寺建成，同样建在高台边缘，前方伸出一座舞台。它是上野公园里最古老的建筑之一，为国家重要文化财产。堂前有一棵枝条弯成圆环的“月之松”。","en":"Kiyomizu Kannon-dō is a hall of Kan’ei-ji temple built in 1631 after the model of Kiyomizu-dera in Kyoto, perched like it on the edge of a terrace with a stage projecting in front. It is one of the oldest buildings in Ueno Park and an Important Cultural Property. Before it grows the \"Moon Pine\", whose branch is trained into a ring."}},
  tytakanawa: {"k":{"zh":"火车站","en":"Railway station"},"y":"2020","a":{"zh":"隈研吾","en":"Kuma Kengo"},"d":{"zh":"高轮Gateway站2020年3月开业，是山手线自1971年西日暮里站以来的第一座新站，位于品川站和田町站之间的旧车辆基地上。车站由隈研吾设计，白色的膜结构大屋顶像折纸一样起伏，覆盖在钢与木材组成的框架上，透进柔和的自然光。","en":"Takanawa Gateway Station opened in March 2020, the first new station on the Yamanote Line since Nishi-Nippori in 1971. It stands between Shinagawa and Tamachi on land of a former rail yard. Designed by Kuma Kengo, it is covered by a great white membrane roof folded like origami over a frame of steel and timber, letting soft daylight into the concourse."}},
  tyyokostadium: {"k":{"zh":"棒球场","en":"Baseball stadium"},"y":"1978","d":{"zh":"横滨球场1978年在横滨公园内落成，看台陡峭，四周立着高高的照明灯塔。它是横滨职业棒球队的主场，前身是1929年建在同一处的横滨公园球场。2021年东京奥运会的棒球和垒球比赛在这里举行，看台为此在赛前进行了扩建。","en":"Yokohama Stadium opened in Yokohama Park in 1978, with steep stands ringed by tall floodlight towers. It is the home ground of Yokohama’s professional baseball team, and an earlier ballpark of 1929 stood on the same spot. The baseball and softball events of the Tokyo Olympics were played here in 2021, and its stands were enlarged beforehand."}},
  tysankeien: {"k":{"zh":"佛塔","en":"Pagoda"},"y":"1457","d":{"zh":"三溪园三重塔原是京都府灯明寺的佛塔，建于1457年，1914年迁到横滨的三溪园，立在园中池塘后面的小山上。它是关东地区现存最古老的木塔，为国家重要文化财产。三溪园是丝绸商人原三溪建造的日本庭园，园中集中了从各地迁来的古建筑。","en":"This three-storey pagoda was built in 1457 for Tōmyō-ji temple in Kyoto Prefecture and moved in 1914 to Sankei-en in Yokohama, where it stands on a hill above the garden’s pond. It is the oldest wooden pagoda in the Kantō region and an Important Cultural Property. Sankei-en is a Japanese garden made by the silk merchant Hara Sankei, filled with old buildings brought from around Japan."}},

  /* sites (same text as the target; used if the target is built as a SITE) */
  "site:tyeastgardens": {"k":{"zh":"庭园","en":"Garden"},"y":"1968","d":{"zh":"皇居东御苑是江户城本丸、二之丸和三之丸的旧址，1968年起对公众开放。园内保留着高大的石垣、护城河、大手门和百人番所，本丸高处还有天守台。江户城天守在1657年明历大火中烧毁后再未重建，只剩下这座石台。","en":"The East Gardens occupy the former inner citadel of Edo Castle and have been open to the public since 1968. Massive stone walls, moats, the Ōtemon gate and the Hyakunin-bansho guardhouse remain, and the stone base of the castle keep stands on the high ground. The keep burned in the Great Fire of 1657 and was never rebuilt, leaving only this platform."},"x":[{"zh":"二之丸一带有传统日式回游庭园","en":"The Ninomaru area has a traditional Japanese stroll garden"}]},
  "site:tykokyogaien": {"k":{"zh":"国民公园","en":"National garden"},"d":{"zh":"皇居外苑是皇居正门前的大片广场，铺着白色碎石，草坪上种着约两千棵修剪成形的黑松。这里四周环绕着护城河和石垣，西南角有江户城的樱田门，东侧立着楠木正成的骑马铜像。从这里可以望见二重桥和伏见橹。","en":"Kokyo Gaien is the broad forecourt in front of the Imperial Palace, a plaza of white gravel with lawns planted with about two thousand trimmed black pines. Moats and stone walls surround it, the Sakuradamon gate of Edo Castle stands at its south-west corner, and a bronze equestrian statue of Kusunoki Masashige stands on the east side. It looks towards Nijūbashi and the Fushimi turret."}},
  "site:tynakamise": {"k":{"zh":"商店街","en":"Shopping street"},"d":{"zh":"仲见世是从雷门通往宝藏门的参道商店街，长约250米，两侧排列着近九十家小店，出售人形烧、仙贝、扇子和各种纪念品。它的起源可以追溯到江户时代，当时附近居民获准在参道上摆摊，是日本最古老的商店街之一。","en":"Nakamise is the shopping street on the temple approach from Kaminarimon to Hōzōmon. About 250 metres long, it is lined with some ninety small shops selling ningyō-yaki cakes, rice crackers, fans and souvenirs. Its origins go back to the Edo period, when local people were allowed to set up stalls along the approach, making it one of Japan’s oldest shopping streets."}},
  "site:tycrossing": {"k":{"zh":"十字路口","en":"Road crossing"},"d":{"zh":"涩谷十字路口位于涩谷站八公口前，信号灯变绿时所有方向的车辆同时停下，行人可以从四面八方甚至斜着穿过。高峰时一次绿灯就有上千人同时过街，它常被称为世界上最繁忙的人行横道之一，四周大楼上的大屏幕让这里昼夜通明。","en":"Shibuya Crossing lies in front of the Hachikō exit of Shibuya Station. When the lights change, all traffic stops at once and pedestrians cross in every direction, even diagonally. At busy times well over a thousand people cross on a single green light, and it is often called one of the busiest crossings in the world. Big video screens on the buildings around it keep it bright day and night."},"x":[{"zh":"旁边有忠犬八公的铜像","en":"The statue of the faithful dog Hachikō stands nearby"}]},
  "site:tymeijijingu": {"k":{"zh":"神社","en":"Shinto shrine"},"y":"1920","d":{"zh":"明治神宫建于1920年，祭祀明治天皇与昭宪皇太后。环绕神社的约70公顷森林是人工种出来的：当年从全国各地献来约十万棵树，按百年后能自然更新的设想栽种，如今已长成都市中心茂密的树林。主殿在空袭中烧毁，1958年重建。","en":"Meiji Jingū was built in 1920 to enshrine Emperor Meiji and Empress Shōken. The forest of about 70 hectares around it was planted by hand: some 100,000 trees donated from all over Japan were set out so the woods would renew themselves over a century, and today they form a dense forest in the city centre. The main halls burned in the air raids and were rebuilt in 1958."},"x":[{"zh":"新年初诣时是日本参拜人数最多的神社之一","en":"At New Year it draws more visitors than almost any other shrine in Japan"}]},
  "site:tystadium": {"k":{"zh":"体育场","en":"Stadium"},"y":"2019","a":{"zh":"隈研吾","en":"Kuma Kengo"},"d":{"zh":"国立竞技场2019年建成，是2020年东京奥运会（2021年举行）的主体育场，建在1958年旧国立竞技场的原址上。外圈层层出挑的屋檐使用了来自日本全部47个都道府县的木材，屋檐上种满绿植，整体高度压得很低，以融入周围的神宫外苑。","en":"The Japan National Stadium was completed in 2019 as the main venue of the Tokyo 2020 Olympics, held in 2021, on the site of the old National Stadium of 1958. Its layered eaves use timber from all 47 prefectures of Japan and are planted with greenery, and the whole stadium is kept low to blend into the Jingū Gaien park around it."}},
  "site:tygyoen": {"k":{"zh":"国民公园","en":"National garden"},"y":"1906","d":{"zh":"新宿御苑原是江户时代高远藩内藤家的宅邸，1906年成为皇室庭园，1949年起向公众开放。园区约58公顷，融合了法式规整园、英式风景园和日本传统庭园三种风格，还有一座大温室。春天约千株樱花盛开，是东京最著名的赏樱地之一。","en":"Shinjuku Gyoen was the Edo-period estate of the Naitō family, lords of Takatō, before becoming an imperial garden in 1906. It has been open to the public since 1949. Its 58 hectares combine a French formal garden, an English landscape garden and traditional Japanese gardens, with a large greenhouse. In spring about a thousand cherry trees make it one of Tokyo’s best-known places for hanami."}},
  "site:tyuenopark": {"k":{"zh":"公园","en":"Park"},"y":"1873","d":{"zh":"上野公园是1873年日本最早指定的公园之一，原是宽永寺的寺域。园内有东京国立博物馆、国立西洋美术馆等多座博物馆和美术馆，有1882年开园的日本最古老的动物园，还有种满莲花的不忍池。春天约八百株樱花盛开。","en":"Ueno Park was among the first parks named in Japan in 1873, on land that once belonged to Kan’ei-ji temple. It holds the Tokyo National Museum, the National Museum of Western Art and many other museums, Japan’s oldest zoo, opened in 1882, and Shinobazu Pond, covered with lotus in summer. In spring some eight hundred cherry trees bloom here."},"x":[{"zh":"园内有西乡隆盛铜像","en":"A bronze statue of Saigō Takamori stands in the park"},{"zh":"勒·柯布西耶设计的国立西洋美术馆是世界遗产","en":"Le Corbusier’s National Museum of Western Art is a World Heritage Site"}]},
  "site:tyakiba": {"k":{"zh":"街区","en":"District"},"d":{"zh":"秋叶原电器街位于中央通两侧，二战后从买卖收音机零件的黑市发展起来，后来成为日本最大的电器街。如今这里还是动漫、游戏和偶像文化的中心，大楼外墙挂满五颜六色的招牌。周日下午中央通常常变成步行街。","en":"Akihabara Electric Town lines both sides of Chūō-dōri. It grew out of a post-war black market for radio parts into Japan’s largest electronics district. Today it is also a centre of anime, games and idol culture, with buildings covered in colourful signs. On Sunday afternoons Chūō-dōri is often closed to traffic as a pedestrian street."}},
  "site:tydomecity": {"k":{"zh":"游乐园","en":"Amusement park"},"y":"1955","d":{"zh":"东京巨蛋城游乐园位于东京巨蛋旁边，前身是1955年开园的后乐园游乐园，2003年改为现名。园中最有名的是没有中心轴的摩天轮，以及从LaQua大楼和摩天轮中间穿过的过山车。它是东京市中心少有的大型游乐设施，晚上灯光很漂亮。","en":"Tokyo Dome City Attractions sits next to Tokyo Dome. It began in 1955 as the Kōrakuen amusement park and took its present name in 2003. Its best-known rides are a Ferris wheel with no hub and a roller coaster that threads through the LaQua building and the wheel itself. It is a rare large amusement park in the middle of Tokyo, bright with lights at night."}},
  "site:tykorakuen": {"k":{"zh":"庭园","en":"Garden"},"d":{"zh":"小石川后乐园是江户时代初期水户德川家的回游式庭园，1629年由德川赖房开始修建，其子德川光圀完成。园名取自范仲淹“先天下之忧而忧，后天下之乐而乐”一句。园内以大泉水为中心，圆月桥倒映水中如满月。","en":"Koishikawa Kōrakuen is an early Edo-period stroll garden of the Mito branch of the Tokugawa family, begun in 1629 by Tokugawa Yorifusa and finished by his son Mitsukuni. Its name comes from a line by the Chinese scholar Fan Zhongyan about enjoying pleasure only after others. The garden centres on a large pond, where the Engetsu-kyō bridge and its reflection make a full moon."},"x":[{"zh":"同时被指定为特别史迹和特别名胜","en":"Designated both a Special Historic Site and a Special Place of Scenic Beauty"}]},
  "site:tykasai": {"k":{"zh":"公园","en":"Park"},"y":"1989","d":{"zh":"葛西临海公园1989年开园，是东京湾边的一座大型海滨公园，有草坪、松林、人工海滩和鸟类保护区。园内的葛西临海水族园由谷口吉生设计，玻璃圆顶下的巨大环形水槽里有成群的金枪鱼游动。公园还有一座观景用的玻璃休息楼。","en":"Kasai Rinkai Park opened in 1989, a large seaside park on Tokyo Bay with lawns, pine woods, man-made beaches and a bird sanctuary. Its aquarium, Tokyo Sea Life Park, was designed by Taniguchi Yoshio: under a glass dome, schools of tuna circle a huge ring-shaped tank. The park also has a glass rest house built for the view."}},
  "site:tydisneyland": {"k":{"zh":"主题公园","en":"Theme park"},"y":"1983","d":{"zh":"东京迪士尼乐园1983年4月开园，位于千叶县浦安市的填海地上，是美国以外的第一座迪士尼主题乐园，由东方乐园公司获授权经营。园区约51公顷，分成多个主题区域，中央是一片环形的河道与湖面。","en":"Tokyo Disneyland opened in April 1983 on reclaimed land in Urayasu, Chiba. It was the first Disney theme park outside the United States and is run by the Oriental Land Company under licence. The park covers about 51 hectares and is divided into several themed lands, with a river circling a lake at its centre."}},
  "site:tydisneysea": {"k":{"zh":"主题公园","en":"Theme park"},"y":"2001","d":{"zh":"东京迪士尼海洋2001年9月开园，与东京迪士尼乐园相邻，以海洋和航海为主题，园内分成多个“港口”区域，中央是一座火山造型的山体。2024年新区域开放后，港口增加到八个。它也由东方乐园公司运营。","en":"Tokyo DisneySea opened in September 2001 next to Tokyo Disneyland. Its theme is the sea and seafaring, and it is laid out as a series of \"ports\" around a mountain shaped like a volcano. A new area opened in 2024, bringing the number of ports to eight. It is also run by the Oriental Land Company."}},
  "site:tychinatown": {"k":{"zh":"街区","en":"District"},"d":{"zh":"横滨中华街是日本最大的唐人街，在1859年横滨开港后逐渐形成，约五百米见方的街区里聚集了数百家餐馆和商店。街区四周立着十座牌楼，东南西北四座分别以青龙、朱雀、白虎、玄武守护。关帝庙是这里的信仰中心。","en":"Yokohama Chinatown is the largest Chinatown in Japan. It took shape after the port opened in 1859, and several hundred restaurants and shops are packed into an area about 500 metres across. Ten decorated gates stand around the district; the four facing east, south, west and north are guarded by the Azure Dragon, Vermilion Bird, White Tiger and Black Tortoise. The Kanteibyō temple to Guan Yu is its spiritual centre."}},
  "site:tyhnd1": {"k":{"zh":"航站楼","en":"Airport terminal"},"y":"1993","d":{"zh":"羽田机场第1航站楼1993年启用，昵称“Big Bird”，主要供国内航班使用。羽田机场1931年开港，后经多次填海扩建，成为日本最繁忙的机场。航站楼屋顶设有展望台，可以近距离看飞机起降，远处还能望见东京湾。","en":"Haneda Terminal 1 opened in 1993 and is nicknamed \"Big Bird\"; it mainly handles domestic flights. Haneda Airport opened in 1931 and has grown through repeated land reclamation into Japan’s busiest airport. The terminal’s rooftop deck gives close views of take-offs and landings, with Tokyo Bay beyond."}},
  "site:tyhnd2": {"k":{"zh":"航站楼","en":"Airport terminal"},"y":"2004","d":{"zh":"羽田机场第2航站楼2004年启用，位于控制塔的东侧，主要供国内航班使用。2020年航站楼增建了国际线设施，开始同时处理国际航班。航站楼与第1航站楼之间有地下通道相连，屋顶同样设有展望台。","en":"Haneda Terminal 2 opened in 2004 east of the control tower and mainly handles domestic flights. In 2020 an international wing was added, so it now handles international flights as well. An underground passage links it to Terminal 1, and it too has a rooftop observation deck."}},
  "site:tyhnd3": {"k":{"zh":"航站楼","en":"Airport terminal"},"y":"2010","d":{"zh":"羽田机场第3航站楼2010年作为国际线航站楼启用，2020年改为现名。航站楼以波浪形大屋顶覆盖出发大厅，楼内还有一条仿照江户街景的商业街。随着羽田国际航线不断增加，这里成了旅客往来东京最便捷的入口之一。","en":"Haneda Terminal 3 opened in 2010 as the International Terminal and took its present name in 2020. A great wave-shaped roof covers its departure hall, and inside is a shopping street modelled on an Edo-period townscape. As Haneda has added more international routes, it has become one of the most convenient gateways to Tokyo."}},
  "site:tybigsight": {"k":{"zh":"会展中心","en":"Convention centre"},"y":"1996","d":{"zh":"东京国际展示场又称东京Big Sight，1996年开馆，是日本最大的会展中心。正门的会议楼由四个倒金字塔并排立在细柱上，造型非常醒目。这里每年举办许多大型展会，夏冬两季的同人志即卖会Comiket也在这里举行。","en":"Tokyo International Exhibition Center, known as Tokyo Big Sight, opened in 1996 and is the largest convention centre in Japan. Its entrance building is a row of four upside-down pyramids standing on slender legs, an unmistakable shape. It hosts many big trade fairs each year, including the summer and winter Comiket self-published comics market."}},
  "site:tytoyosu": {"k":{"zh":"批发市场","en":"Wholesale market"},"y":"2018","d":{"zh":"丰洲市场2018年10月开业，取代了已运营八十多年的筑地市场，是东京最大的鲜鱼与蔬果批发市场。市场分成几栋大楼，参观者可以沿着专用通道隔窗观看金枪鱼拍卖。水产仲卸卖场楼的屋顶上有一片绿化庭园。","en":"Toyosu Market opened in October 2018, replacing the Tsukiji market after more than eighty years, and is Tokyo’s main wholesale market for fish, fruit and vegetables. It is split into several large buildings, and visitors can watch the tuna auctions through windows from dedicated walkways. The intermediate-wholesale fish building has a garden on its roof."}},
  "site:tymakuhari": {"k":{"zh":"会展中心","en":"Convention centre"},"y":"1989","a":{"zh":"槙文彦","en":"Maki Fumihiko"},"d":{"zh":"幕张展览馆1989年开馆，由槙文彦设计，位于千叶市海边的幕张新都心。展厅的金属屋顶连成一道起伏的波浪线，旁边还有国际会议厅和活动大厅。东京游戏展每年都在这里举行，过去东京车展也曾长期在此举办。","en":"Makuhari Messe opened in 1989, designed by Maki Fumihiko, in the Makuhari new town by the sea in Chiba City. The metal roofs of its exhibition halls form one long undulating wave, alongside an international conference hall and an event hall. The Tokyo Game Show is held here every year, and for many years the Tokyo Motor Show was too."}},
  "site:tyyasukuni": {"k":{"zh":"神社","en":"Shinto shrine"},"y":"1869","d":{"zh":"靖国神社创建于1869年，最初名为东京招魂社，1879年改为现名，祭祀幕末以来在战争中为国家死去的人。参道上依次立着高大的钢制第一鸟居和桧木神门，后方是拜殿与本殿。由于它与战争记忆的关系，这座神社常引起国内外争议。","en":"Yasukuni Shrine was founded in 1869 as Tokyo Shōkonsha and took its present name in 1879. It enshrines those who died for the country in wars since the end of the Edo period. The approach passes a tall steel first torii and a cypress gate before the worship hall and main hall. Its place in the memory of war makes it a subject of debate in Japan and abroad."},"x":[{"zh":"境内一棵染井吉野是东京樱花开花的观测标准木","en":"A cherry tree here is the official sample tree for Tokyo’s blossom forecast"}]},
  "site:tysensoji": {"k":{"zh":"佛教寺院","en":"Buddhist temple"},"y":"1958","d":{"zh":"浅草寺是东京最古老的寺院，相传628年两兄弟在隅田川中捞到一尊观音像，由此创建。本堂又称观音堂，在1945年空袭中烧毁，1958年用钢筋混凝土重建，保留了陡峭的大屋顶和朱红色立柱。2010年屋顶换成了钛金属瓦。","en":"Sensō-ji is Tokyo’s oldest temple. By tradition it was founded in 628, after two brothers fishing in the Sumida River found a statue of Kannon in their net. The main hall, or Kannon-dō, burned in the 1945 air raids and was rebuilt in concrete in 1958, keeping its steep sweeping roof and vermilion columns. In 2010 the roof was re-tiled in titanium."}},
  "site:tyzojoji": {"k":{"zh":"佛教寺院","en":"Buddhist temple"},"y":"1974","d":{"zh":"增上寺是净土宗的大本山，江户时代是德川将军家的菩提寺，境内葬有六位将军。寺内大殿在二战空袭中烧毁，现在的大殿于1974年重建完成。从大殿前望去，东京塔就在背后，古寺与铁塔同框是这里最有名的景色。","en":"Zōjō-ji is a head temple of the Jōdo sect of Buddhism. In the Edo period it was the family temple of the Tokugawa shoguns, and six shoguns are buried here. Its main hall burned in the wartime air raids; the present Daiden was completed in 1974. Seen from the front, the hall with Tokyo Tower rising behind it is one of the city’s best-known views."}},
  "site:tyhamarikyu": {"k":{"zh":"日本庭园","en":"Japanese garden"},"d":{"zh":"滨离宫恩赐庭园是江户时代德川将军家的庭园，这片海边原是将军的猎鹰场，后来成为将军的别邸“滨御殿”。明治以后它成为皇室的离宫，1945年赐给东京市，次年对外开放。园中的潮入之池引入东京湾的海水，水位随潮汐涨落，池中小岛上建有中岛御茶屋。","en":"Hama-rikyū was a garden of the Tokugawa shoguns. This shore was first a falconry ground and later became the shogun’s villa, Hama Goten. After the Meiji Restoration it was an imperial detached palace; it was given to the city of Tokyo in 1945 and opened the following year. Its Shioiri Pond takes in seawater from Tokyo Bay and rises and falls with the tide, and the Nakajima teahouse stands on an island in it."}},

  /* site building labels */
  "site:tymeijijingu:Meiji Jingū Main Shrine": {"p":"site:tymeijijingu:Main Shrine"},
  "site:tymeijijingu:Meiji Jingū Museum": {"p":"site:tymeijijingu:Meiji Shrine Museum"},
  "site:tygyoen:Taiwan Pavilion (Kyū-Goryōtei)": {"p":"site:tygyoen:Taiwan Pavilion"},
  "site:tyuenopark:Kiyomizu Kannon-dō": {"k":{"zh":"佛堂","en":"Buddhist hall"},"y":"1631","d":{"zh":"清水观音堂是宽永寺的一座佛堂，1631年仿照京都清水寺建成，同样建在高台边缘，前方伸出一座舞台。它是上野公园里最古老的建筑之一，为国家重要文化财产。堂前有一棵枝条弯成圆环的“月之松”。","en":"Kiyomizu Kannon-dō is a hall of Kan’ei-ji temple built in 1631 after the model of Kiyomizu-dera in Kyoto, perched like it on the edge of a terrace with a stage projecting in front. It is one of the oldest buildings in Ueno Park and an Important Cultural Property. Before it grows the \"Moon Pine\", whose branch is trained into a ring."}},
  "site:tyuenopark:Ueno Toshogu": {"k":{"zh":"神社","en":"Shinto shrine"},"y":"1651","d":{"zh":"上野东照宫祭祀德川家康，现在的社殿是1651年由三代将军德川家光重建的，金碧辉煌，被称为“金色殿”。它躲过了地震和战火，保存至今，社殿为国家重要文化财产。参道两旁排列着各地大名献纳的石灯笼和铜灯笼。","en":"Ueno Tōshōgū enshrines Tokugawa Ieyasu. Its present buildings were rebuilt in 1651 by the third shogun, Tokugawa Iemitsu, and are so richly gilded that the main shrine is called the Golden Hall. They have survived earthquakes and war and are Important Cultural Properties. The approach is lined with stone and bronze lanterns given by feudal lords."}},
  "site:tyuenopark:Shinobazu no ike Bentendo": {"k":{"zh":"佛堂","en":"Buddhist hall"},"d":{"zh":"不忍池辩天堂建在不忍池中的小岛上，供奉辩才天，是宽永寺的一部分。江户时代初期，人们仿照琵琶湖的竹生岛在池中筑岛建堂。原来的佛堂在二战中烧毁，现在的八角形佛堂为战后重建。夏天四周开满莲花。","en":"Bentendō stands on an island in Shinobazu Pond and is dedicated to the goddess Benzaiten; it belongs to Kan’ei-ji temple. In the early Edo period the island and hall were built in imitation of Chikubushima on Lake Biwa. The original hall burned in the war, and the present octagonal hall is a post-war rebuilding. In summer it is surrounded by lotus."}},
  "site:tyuenopark:Tokyo Bunka Kaikan": {"k":{"zh":"音乐厅","en":"Concert hall"},"y":"1961","a":{"zh":"前川国男","en":"Maekawa Kunio"},"d":{"zh":"东京文化会馆1961年开馆，由前川国男设计，就在上野站公园口的正对面。大大的混凝土屋檐向上翘起，与对面勒·柯布西耶设计的国立西洋美术馆相呼应。它是东京最早的正式音乐厅之一，常上演古典音乐、歌剧和芭蕾。","en":"Tokyo Bunka Kaikan opened in 1961, designed by Maekawa Kunio, right opposite the park exit of Ueno Station. Its great upturned concrete eaves answer the National Museum of Western Art by Le Corbusier across the way. It was one of Tokyo’s first proper concert halls and stages classical music, opera and ballet."}},
  "site:tyuenopark:The Gallery of Horyuji Treasures": {"k":{"zh":"博物馆","en":"Museum"},"y":"1999","a":{"zh":"谷口吉生","en":"Taniguchi Yoshio"},"d":{"zh":"法隆寺宝物馆是东京国立博物馆的一座展馆，1999年开馆，由谷口吉生设计。简洁的玻璃与石材立面倒映在门前的浅水池中。馆内收藏着明治时代法隆寺献给皇室的约三百件宝物，以七世纪前后的佛像和工艺品为主。","en":"The Gallery of Hōryū-ji Treasures is part of the Tokyo National Museum, opened in 1999 and designed by Taniguchi Yoshio. Its clean glass and stone front is reflected in a shallow pool before the entrance. Inside are about three hundred treasures given by Hōryū-ji temple to the Imperial Household in the Meiji era, many of them Buddhist statues and crafts from around the seventh century."}},
  "site:tyeastgardens:Tokagakudo Concert Hall": {"k":{"zh":"音乐厅","en":"Concert hall"},"y":"1966","d":{"zh":"桃华乐堂建于1966年，为纪念香淳皇后六十岁寿辰而建，供宫内厅乐部演奏使用。这座八角形的小音乐厅外墙贴着彩色马赛克瓷砖，顶部像一顶带棱的帽子，在东御苑的古城石垣之间显得别具一格。","en":"Tōkagakudō was built in 1966 to mark the sixtieth birthday of Empress Kōjun and is used for performances by the Imperial Household’s musicians. The small octagonal hall is faced with colourful mosaic tiles and topped by a ribbed, hat-like roof, standing out among the old castle walls of the East Gardens."}},
  "site:tymeijijingu:Main Shrine": {"k":{"zh":"神社社殿","en":"Shrine hall"},"y":"1958","d":{"zh":"明治神宫的主社殿位于森林深处，由本殿、拜殿和回廊围成一个宽阔的庭院，用桧木建造，覆以铜板屋顶，风格朴素。1920年的初建社殿在1945年空袭中烧毁，现在的社殿是1958年重建的。庭院里有一对被称为“夫妇楠”的樟树。","en":"The main shrine of Meiji Jingū lies deep in the forest: the main hall, the worship hall and covered corridors around a wide courtyard, built of cypress under copper roofs in a plain style. The first buildings of 1920 burned in the 1945 air raids, and the present ones were rebuilt in 1958. A pair of camphor trees in the courtyard is known as the \"married couple\"."}},
  "site:tymeijijingu:Meiji Shrine Museum": {"k":{"zh":"博物馆","en":"Museum"},"y":"2019","a":{"zh":"隈研吾","en":"Kuma Kengo"},"d":{"zh":"明治神宫博物馆2019年开馆，由隈研吾设计，低矮的建筑掩映在神宫的森林里，深远的屋檐和木质细部与周围的树木融为一体。馆内展出与明治天皇和昭宪皇太后有关的文物，包括天皇曾乘坐的马车。","en":"The Meiji Jingū Museum opened in 2019, designed by Kuma Kengo. The low building sits among the shrine’s trees, its deep eaves and timber details blending with the forest. It displays objects associated with Emperor Meiji and Empress Shōken, including a carriage the emperor rode in."}},
  "site:tygyoen:Taiwan Pavilion": {"k":{"zh":"亭阁","en":"Pavilion"},"y":"1927","d":{"zh":"旧御凉亭又称台湾阁，1927年由在台湾的日本人为纪念昭和天皇（当时为皇太子）大婚而捐建，是日本少见的中国南方风格建筑。它立在新宿御苑的池边，从亭中可以看到池水与对岸的日本庭园。现为东京都选定的历史建筑。","en":"The Kyū-Goryōtei, or Taiwan Pavilion, was built in 1927, a gift from Japanese living in Taiwan to mark the wedding of the future Emperor Shōwa. It is a rare example in Japan of southern Chinese architecture. It stands at the edge of a pond in Shinjuku Gyoen, looking across the water to the Japanese garden. It is a selected historic building of Tokyo."}},
  "site:tygyoen:Greenhouse": {"k":{"zh":"温室","en":"Greenhouse"},"y":"2012","d":{"zh":"新宿御苑大温室2012年重新建成开放。新宿御苑早在明治时代就开始建温室栽培热带植物和兰花，是日本近代园艺的发源地之一。现在的温室里种着约2700种热带和亚热带植物，包括珍稀濒危的品种。","en":"The large greenhouse of Shinjuku Gyoen reopened in a new building in 2012. Greenhouses for tropical plants and orchids were first built here in the Meiji era, making the garden one of the birthplaces of modern horticulture in Japan. Today about 2,700 kinds of tropical and subtropical plants grow inside, including rare and endangered ones."}},
  "site:tynakamise:Asakusa Culture and Tourism Center": {"k":{"zh":"游客中心","en":"Visitor centre"},"y":"2012","a":{"zh":"隈研吾","en":"Kuma Kengo"},"d":{"zh":"浅草文化观光中心就在雷门的斜对面，2012年开馆，由隈研吾设计。这座八层的小楼像是把几栋坡屋顶的木房子一层层叠起来，外墙覆着木条格栅。顶层的免费观景台可以俯瞰仲见世和晴空塔。","en":"The Asakusa Culture Tourist Information Center stands across the street from Kaminarimon. Opened in 2012 and designed by Kuma Kengo, the eight-storey building looks like a stack of small pitched-roof wooden houses, wrapped in timber louvres. Its free top-floor terrace looks down on Nakamise and across to the Skytree."}},
  "site:tydomecity:LaQua": {"k":{"zh":"商业设施","en":"Leisure complex"},"y":"2003","d":{"zh":"LaQua是东京巨蛋城的综合娱乐设施，2003年开业，楼里有温泉水疗、商店和餐厅。它最特别的地方是过山车直接从建筑中间的空洞穿过，旁边的无中心轴摩天轮也嵌在大楼之间，成为这里的标志性画面。","en":"LaQua is the leisure complex of Tokyo Dome City, opened in 2003, with a hot-spring spa, shops and restaurants. Its most unusual feature is the roller coaster that shoots straight through an opening in the building, while the hubless Ferris wheel is set in among its blocks, together making the area’s best-known picture."}},
  "site:tytoyosu:Fish Wholesale Market Building": {"k":{"zh":"市场大楼","en":"Market building"},"y":"2018","d":{"zh":"水产批发卖场楼是丰洲市场举行金枪鱼拍卖的地方。凌晨时分，一排排冷冻金枪鱼摆满卖场，批发商们逐一检查后竞价。参观者可以从楼上的参观通道隔着玻璃观看，还可以预约在更近的观景台上观看。","en":"The Fish Wholesale Market Building is where Toyosu’s tuna auctions take place. In the early morning rows of frozen tuna fill the floor, and buyers inspect them one by one before bidding. Visitors can watch through glass from the gallery above, and can book a place on a closer viewing deck."}},
  "site:tymakuhari:International Conference Hall": {"k":{"zh":"会议中心","en":"Conference centre"},"y":"1989","a":{"zh":"槙文彦","en":"Maki Fumihiko"},"d":{"zh":"国际会议厅是幕张展览馆的会议设施，与展览馆同在1989年开业，由槙文彦设计。楼内有多个大小会议室和一座大厅，可以与旁边的展厅配合举办国际会议和学术会议。它与展厅一起面向东京湾展开。","en":"The International Conference Hall is the meeting building of Makuhari Messe, opened with the exhibition halls in 1989 and designed by Maki Fumihiko. It holds conference rooms of many sizes and a main hall, working together with the exhibition halls next door for international and academic meetings. Like them, it faces Tokyo Bay."}},
  "site:tybigsight:Conference Tower": {"k":{"zh":"会议楼","en":"Conference building"},"y":"1996","d":{"zh":"会议楼是东京Big Sight最醒目的部分：四个倒金字塔形的大体块并排立在细长的支柱上，下方是开阔的入口广场。倒金字塔里是大小会议室和餐厅，从远处的海上和高速公路上都能一眼认出。","en":"The Conference Tower is the most striking part of Tokyo Big Sight: four large upside-down pyramids standing side by side on slender legs above an open entrance plaza. The pyramids hold conference rooms and restaurants, and the shape can be recognised at once from the bay and the expressways around it."}},

  /* far terrain (Mount Fuji, the lakes, Hakone, Tanzawa, Sagami Bay) */
  "far:fuji": {"k":{"zh":"火山","en":"Volcano"},"h":3776,"d":{"zh":"富士山海拔3776米，是日本最高的山，位于静冈县与山梨县交界处，距东京约一百公里。它是一座典型的成层火山，最近一次喷发是1707年的宝永喷发。2013年以“富士山——信仰的对象与艺术的源泉”被列入世界文化遗产。晴天时从东京的高楼上就能望见。","en":"Mount Fuji, 3,776 metres high, is the highest mountain in Japan, on the border of Shizuoka and Yamanashi about 100 kilometres from Tokyo. It is a classic stratovolcano whose last eruption was the Hōei eruption of 1707. In 2013 it became a World Heritage Site as a sacred place and source of artistic inspiration. On clear days it can be seen from Tokyo’s high towers."},"x":[{"zh":"最高点名为剑峰","en":"The highest point is called Kengamine"},{"zh":"登山季节一般在七月至九月","en":"The climbing season is usually July to September"}]},
  "far:fivelakes": {"k":{"zh":"湖泊群","en":"Lakes"},"d":{"zh":"富士五湖是富士山北麓的五个湖泊：山中湖、河口湖、西湖、精进湖和本栖湖，都是富士山的火山活动堵塞河谷而形成的。这里是眺望富士山倒影的著名地方，一带属于富士箱根伊豆国立公园。","en":"The Fuji Five Lakes lie along the northern foot of Mount Fuji: Yamanaka, Kawaguchi, Sai, Shōji and Motosu. All were formed when volcanic activity on Fuji dammed the valleys. The area is famous for views of the mountain reflected in the water and is part of Fuji-Hakone-Izu National Park."}},
  "far:yamanaka": {"k":{"zh":"湖泊","en":"Lake"},"d":{"zh":"山中湖是富士五湖中面积最大、湖面海拔最高的一个，湖面约在海拔980米。它离富士山很近，湖边可以看到富士山正面的雄姿，冬天有时还能看到“钻石富士”——太阳正好落在山顶的景象。","en":"Lake Yamanaka is the largest of the Fuji Five Lakes and the one with the highest surface, at about 980 metres above sea level. It lies close to the mountain, giving broad views of Fuji’s face, and in winter it is a place to see \"Diamond Fuji\", when the sun sets exactly on the summit."}},
  "far:kawaguchi": {"k":{"zh":"湖泊","en":"Lake"},"d":{"zh":"河口湖是富士五湖中开发最充分、交通最方便的一个，湖边分布着温泉旅馆、美术馆和游船码头。从北岸望去，富士山连同它的倒影一起映在湖面上，是最常见的富士山风景照之一。","en":"Lake Kawaguchi is the most developed and easiest to reach of the Fuji Five Lakes, with hot-spring inns, museums and boat piers along its shores. From the north shore Mount Fuji appears together with its reflection on the water, one of the most photographed views of the mountain."}},
  "far:sai": {"k":{"zh":"湖泊","en":"Lake"},"d":{"zh":"西湖位于青木原树海的北侧，湖岸幽静。它原本和精进湖同属一个大湖，864年富士山贞观喷发的熔岩流入后才被分开，两湖与本栖湖的水面高度至今几乎相同。2010年人们在西湖发现了一度被认为已灭绝的国鳟。","en":"Lake Sai lies on the north side of the Aokigahara forest and has quiet shores. It was once part of a larger lake together with Lake Shōji, until lava from Fuji’s Jōgan eruption of 864 split them; their water levels, and that of Lake Motosu, are still almost the same. In 2010 the kunimasu, a fish thought to be extinct, was found living here."}},
  "far:shoji": {"k":{"zh":"湖泊","en":"Lake"},"d":{"zh":"精进湖是富士五湖中最小的一个，三面被山环抱，湖畔安静。从北岸看去，富士山前方叠着一座较小的大室山，好像母亲抱着孩子，因而被称为“抱子富士”。冬天湖面有时会结冰。","en":"Lake Shōji is the smallest of the Fuji Five Lakes, enclosed by hills on three sides with quiet shores. From the north shore the smaller Mount Ōmuro appears in front of Fuji, like a mother holding a child, a view known as \"Kodaki Fuji\". In cold winters the lake sometimes freezes."}},
  "far:motosu": {"k":{"zh":"湖泊","en":"Lake"},"d":{"zh":"本栖湖是富士五湖中最西、最深的一个，湖水清澈，呈深蓝色。从湖的北岸望见的富士山倒影，被印在2004年发行的千元日钞背面，是日本人非常熟悉的风景。湖面海拔约九百米。","en":"Lake Motosu is the westernmost and deepest of the Fuji Five Lakes, with clear, deep-blue water. The view of Fuji and its reflection from the north shore was printed on the back of the 1,000-yen note issued from 2004, making it a familiar picture in Japan. Its surface lies about 900 metres above sea level."}},
  "far:ashi": {"k":{"zh":"湖泊","en":"Lake"},"d":{"zh":"芦之湖位于箱根火山的火口原，湖面海拔约720米，是箱根的中心景点。湖上有仿古帆船样式的观光船往来，湖岸箱根神社的红色“平和鸟居”立在水中。晴天时可以从湖上望见远处的富士山。","en":"Lake Ashi lies in the caldera of the Hakone volcano at about 720 metres above sea level and is the heart of the Hakone area. Sightseeing boats styled like old sailing ships cross the lake, and the red \"Torii of Peace\" of Hakone Shrine stands in the water by the shore. On clear days Mount Fuji appears in the distance."}},
  "far:hakone": {"k":{"zh":"温泉地","en":"Hot-spring area"},"d":{"zh":"箱根是神奈川县西部的一座火山和著名温泉地，距东京约八十公里。火口原里有芦之湖，大涌谷至今仍冒着硫磺蒸汽，用地热煮成的“黑鸡蛋”是这里的特产。每年一月二日和三日，大学生的箱根驿传接力赛从东京跑到这里再折返。","en":"Hakone is a volcano and famous hot-spring area in western Kanagawa, about 80 kilometres from Tokyo. Its caldera holds Lake Ashi, and the Ōwakudani valley still steams with sulphur, where eggs boiled in the hot springs turn black. Every year on 2 and 3 January, the Hakone Ekiden university relay runs from Tokyo to Hakone and back."}},
  "far:tanzawa": {"k":{"zh":"山地","en":"Mountain range"},"d":{"zh":"丹泽山地位于神奈川县西北部，是东京和横滨西边最近的一片高山，最高峰蛭岳海拔1673米。山中溪谷众多，林木茂密，是首都圈登山者常去的地方。冬天从东京望去，积雪的丹泽群山后面常露出富士山的山顶。","en":"The Tanzawa Mountains in north-western Kanagawa are the nearest high mountains west of Tokyo and Yokohama; the highest peak, Hirugatake, rises to 1,673 metres. Their deep valleys and dense forests are popular with hikers from the capital region. In winter, seen from Tokyo, Fuji’s summit often peeks out behind the snowy Tanzawa ridges."}},
  "far:sagami": {"k":{"zh":"海湾","en":"Bay"},"d":{"zh":"相模湾位于神奈川县南面，东起三浦半岛，西至伊豆半岛。沿岸有镰仓、江之岛和湘南海岸等著名海滨，湾内海底非常深。1923年关东大地震的震源就在相模湾一带。晴天时从湘南海边可以隔海望见富士山。","en":"Sagami Bay lies south of Kanagawa, between the Miura Peninsula in the east and the Izu Peninsula in the west. Its shores include Kamakura, Enoshima and the Shōnan coast, and the sea floor of the bay drops very deep. The 1923 Great Kantō Earthquake began beneath the Sagami Bay area. On clear days Mount Fuji can be seen across the water from the Shōnan beaches."}},
});
